window.__TL=[{"src": [1], "date": "1845-12-29", "display_date": "December 29, 1845", "title": "Texas Becomes the 28th State", "text": "Congress accepts the Texas state constitution, and Texas legally enters the Union as the 28th state.", "source": "Handbook of Texas Online, \"Annexation\"", "url": "https://www.tshaonline.org/handbook/entries/annexation", "cats": ["national"], "key": false, "status": "VERIFIED"}, {"src": [2], "date": "1849-02-08", "display_date": "February 8, 1849", "title": "Lansing Stephen Thorne Is Born", "text": "Lansing Stephen Thorne is born near Greenville, New York. He joined the Texas and Pacific as trainmaster in 1874, became vice president and general manager in 1893, and died in Dallas on February 28, 1917.", "source": "New Encyclopedia of Texas, biography of Lansing Stephen Thorne (copy in JS's research files)", "url": "", "cats": ["certificate"], "key": false, "status": "CORRECTED"}, {"src": [3], "date": "1852-02-16", "display_date": "February 16, 1852", "title": "Texas Charters the Texas Western Railroad", "text": "The Texas Legislature charters the Texas Western Railroad Company to build from the eastern border of Texas to El Paso. The act was captioned the Vicksburg and El Paso Railroad Company, but the body of the charter called the line the Texas Western. Railroad charters of 1852 typically carried a grant of eight sections of land per mile.", "source": "Handbook of Texas Online, \"Texas Western Railroad\" and \"Railroads\"", "url": "https://www.tshaonline.org/handbook/entries/texas-western-railroad", "cats": ["railroad", "land"], "key": false, "status": "CORRECTED"}, {"src": [4, 5, 6, 7], "date": "1853-08-31", "display_date": "August 31, 1853", "title": "Sexton and Starr Collect Texas Western Subscriptions", "text": "At a Texas Western stockholders meeting, F. B. Sexton is elected secretary and James Harper Starr a director. Letters from Sexton to Starr through 1853 and 1854 show Starr collecting stock subscription payments in Nacogdoches, including a receipt of January 14, 1854, for $139 sent on to Sexton.", "source": "James Harper Starr Papers, Box 2R189, Briscoe Center for American History, University of Texas at Austin (Sexton letters of Sept. 6 and Sept. 26, 1853; receipt of Jan. 14, 1854)", "url": "", "cats": ["railroad"], "key": false, "status": "RECORD-ONLY"}, {"src": [8], "date": "1854-01-30", "display_date": "January 30, 1854", "title": "Texas Offers 16 Sections of Land per Mile", "text": "A general law, \"an act to encourage the Construction of Rail Roads in Texas by donation of land,\" offers railroads sixteen sections (10,240 acres) of public land for each mile of road built. The law stayed in effect until the Constitution of 1869.", "source": "Handbook of Texas Online, \"Railroads\"; Southern Pacific acceptance resolution of Dec. 19, 1857, Texas State Library and Archives (quoting the act's title and date)", "url": "https://www.tshaonline.org/handbook/entries/railroads", "cats": ["land", "railroad"], "key": false, "status": "VERIFIED"}, {"src": [9], "date": "1856-08-16", "display_date": "August 16, 1856", "title": "Texas Western Renamed the Southern Pacific", "text": "The legislature, over the governor's veto, renames the company the Southern Pacific Railroad Company. This Texas company is not the later California-based Southern Pacific system.", "source": "Handbook of Texas Online, \"Texas Western Railroad\"; Stevenson v. Texas Railway Co., 105 U.S. 703 (1882), at 704", "url": "https://www.tshaonline.org/handbook/entries/texas-western-railroad", "cats": ["railroad"], "key": false, "status": "VERIFIED"}, {"src": [10], "date": "1857-12-19", "display_date": "December 19, 1857", "title": "Southern Pacific Accepts State Land and Loan Laws", "text": "The company's board resolves to accept the land-grant law of January 30, 1854, and the law of August 13, 1856, for investing the state's Special School Fund in railroad bonds, and sends certified copies to the governor, treasurer and land commissioner.", "source": "Southern Pacific Railroad acceptance resolution, Dec. 19, 1857, Records relating to railroads, Texas State Library and Archives Commission", "url": "https://www.tsl.texas.gov/exhibits/railroad/beginnings/southernpacific-acceptance.html", "cats": ["railroad", "land"], "key": false, "status": "CORRECTED"}, {"src": [11, 14], "date": "1858", "display_date": "1857 to 1858", "title": "First Track Runs from Caddo Lake to Marshall", "text": "The Southern Pacific builds its first line, about 23 to 25 miles, between Swanson's Landing on Caddo Lake and Marshall, and begins service with ox-drawn cars until its locomotive arrives. The Supreme Court later wrote that before September 1859 the company had completed twenty-five miles and had earned, \"it is claimed,\" about 256,000 acres of land.", "source": "Handbook of Texas Online, \"Texas Western Railroad\" (23 miles built during 1857); Texas State Library and Archives, \"Southern Pacific Acceptance Letter\" exhibit (1858 ox-drawn service); Stevenson v. Texas Railway Co., 105 U.S. 703 (1882), at 704", "url": "https://www.tshaonline.org/handbook/entries/texas-western-railroad", "cats": ["railroad", "marshall", "land"], "key": false, "status": "CORRECTED"}, {"src": [12], "date": "1858-07-20", "display_date": "July 20, 1858", "title": "A Stockholder Writes of a \"Foul Conspiracy\"", "text": "Thomas H. Wiley writes to Col. Richard T. Archer that the stockholders \"have been sold out by a foul conspiracy\" and that \"by the late sale all the stockholders out of Texas were to be cut off.\" He reports that stockholders had taken possession of the company's New Orleans office and papers.", "source": "Thomas H. Wiley to Col. Richard T. Archer, July 20, 1858, Briscoe Center for American History, University of Texas at Austin (cited in JS's files to the James Harper Starr Papers)", "url": "", "cats": ["railroad"], "key": false, "status": "RECORD-ONLY"}, {"src": [13], "date": "1858-08-09", "display_date": "August 9, 1858", "title": "Dr. Jeptha Fowlkes Elected President", "text": "Shareholders elect Dr. Jeptha Fowlkes of Memphis president of the Southern Pacific.", "source": "Harrison Flag Extra (Marshall, Texas), Oct. 22, 1858", "url": "", "cats": ["railroad"], "key": false, "status": "RECORD-ONLY"}, {"src": [15, 16], "date": "1858-11-22", "display_date": "November 22, 1858", "title": "Stockholders Adopt the 50-Cent Call", "text": "A stockholders convention votes to cut every holder's shares in half and to call 50 cents on each remaining share to save the company. The plan was presented to shareholders again at a meeting on April 15, 1859.", "source": "DeBow's Review, Vol. 25 (1858); Louisville Journal, Apr. 29, 1859 (report of the Apr. 15, 1859 meeting)", "url": "", "cats": ["railroad", "certificate"], "key": false, "status": "RECORD-ONLY"}, {"src": [17], "date": "1859-06-10", "display_date": "June 10, 1859", "title": "Certificate No. 1656 Issued to Mrs. Mary Key", "text": "The Southern Pacific Railroad Company issues Certificate No. 1656 to Mrs. Mary Key for 300 shares at $100 par, a face value of $30,000. It is signed by D. D. Wilder, Secretary. The certificate descended through the Thorne family to John Stephen Thorne, who holds it today.", "source": "Certificate No. 1656 (original); Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (filed Nov. 2026), para. 10", "url": "", "cats": ["certificate"], "key": true, "status": "CORRECTED"}, {"src": [18], "date": "1859-09-06", "display_date": "September 6, 1859", "title": "Railroad Sold to R. V. Richardson", "text": "Insolvent, the Southern Pacific is sold under execution on a judgment to R. V. Richardson of Memphis. The sale was made under an 1853 Texas law that let the buyer of a railroad's road and franchise take over its charter.", "source": "Stevenson v. Texas Railway Co., 105 U.S. 703 (1882), at 704 to 705", "url": "https://www.govinfo.gov/content/pkg/USREPORTS-105/pdf/USREPORTS-105-703.pdf", "cats": ["railroad", "courts"], "key": false, "status": "VERIFIED"}, {"src": [19], "date": "1859-10-03", "display_date": "October 3, 1859", "title": "Richardson Reorganizes the Company", "text": "Richardson and his associates reorganize the Southern Pacific with a new capital stock, most of it subscribed by Richardson and Jeptha Fowlkes, and elect a board on October 3, 1859. The company's corporate book records a September 29, 1859 meeting admitting stockholders who had paid the call. In 1861 the New Orleans Daily Crescent reported Richardson saying he \"was under no legal obligations to take in anybody\" but \"respected their rights.\"", "source": "Stevenson v. Texas Railway Co., 105 U.S. 703 (1882), at 705; Southern Pacific Railroad Company corporate book, pp. 33 to 39 (Sept. 29, 1859 meeting); New Orleans Daily Crescent, Mar. 28, 1861", "url": "https://csa-railroads.com/Essays/Orignial%20Docs/NP/NODC/NP,_NODC_3-28-61.htm", "cats": ["railroad", "certificate"], "key": false, "status": "CORRECTED"}, {"src": [20], "date": "1860-01-14", "display_date": "January 14, 1860", "title": "J. Edgar Thomson Named President", "text": "According to the appellants' brief in the later Stevenson case, J. Edgar Thomson, president of the Pennsylvania Railroad, became president of the Southern Pacific in January 1860.", "source": "Appellants' Brief, Stevenson v. Texas & Pacific Railway Co., p. 3; Certificate No. 3137, Southern Pacific Railroad Company", "url": "", "cats": ["railroad"], "key": false, "status": "RECORD-ONLY"}, {"src": [21], "date": "1860-08-06", "display_date": "August 6, 1860", "title": "V. K. Stevenson Elected President", "text": "Vernon K. Stevenson of Tennessee is elected president of the Southern Pacific, and an executive committee that includes Fowlkes and Richardson is given the powers of the board.", "source": "Appellants' Brief, Stevenson v. Texas & Pacific Railway Co., p. 3; Appellants' Transcript of Evidence; New Orleans Daily Crescent, Mar. 28, 1861 (Stevenson as president; executive committee)", "url": "", "cats": ["railroad"], "key": false, "status": "RECORD-ONLY"}, {"src": [22], "date": "1860-08-25", "display_date": "August 25, 1860", "title": "Company Mortgages Its Road and Lands", "text": "The reorganized company executes two mortgages to R. V. Richardson and Vernon K. Stevenson as trustees: one for a proposed $25 million bond issue covering all its property and land grant, the other covering one million acres of the land grant. The mortgages were not recorded in Harrison County until March 1, 1861.", "source": "Stevenson v. Texas Railway Co., 105 U.S. 703 (1882), at 705", "url": "https://www.govinfo.gov/content/pkg/USREPORTS-105/pdf/USREPORTS-105-703.pdf", "cats": ["railroad", "land", "courts"], "key": false, "status": "CORRECTED"}, {"src": [23], "date": "1861-02-01", "display_date": "February 1, 1861", "title": "Texas Secedes", "text": "The Texas Secession Convention adopts an ordinance of secession, which voters approve on February 23, 1861.", "source": "Handbook of Texas Online, \"Secession Convention\"", "url": "https://www.tshaonline.org/handbook/entries/secession-convention", "cats": ["national"], "key": false, "status": "VERIFIED"}, {"src": [24], "date": "1861-03-15", "display_date": "March 15, 1861", "title": "The Louisville Call of $1 per Share", "text": "At a stockholders meeting in Louisville, Kentucky, President V. K. Stevenson asks every holder to subscribe $1 per share, half in cash and half in six months, to pay the company's debts and finish fifty more miles of road. Meetings in Memphis and New Orleans followed, and Dr. Fowlkes wrote that \"all who pay will be protected, and all who do not must give up the enterprise.\"", "source": "Nashville Union and American, Mar. 16, 1861 (from the Louisville Journal, Mar. 15); Nashville Patriot, Mar. 16, 1861; Memphis Avalanche, Apr. 16, 1861; New Orleans Daily Crescent, Mar. 28 and Apr. 16, 1861 (Fowlkes letter of Apr. 2, 1861)", "url": "https://csa-railroads.com/Essays/Orignial%20Docs/NP/Misc/NP,_NUA_3-16-61.htm", "cats": ["railroad", "certificate"], "key": false, "status": "CORRECTED"}, {"src": [25], "date": "1861-04-12", "display_date": "April 12, 1861", "title": "Civil War Begins at Fort Sumter", "text": "Confederate forces fire on Fort Sumter in Charleston Harbor, and the Civil War begins.", "source": "National Park Service, Fort Sumter and Fort Moultrie National Historical Park", "url": "https://www.nps.gov/fosu/index.htm", "cats": ["national"], "key": false, "status": "VERIFIED"}, {"src": [26], "date": "1861-09-03", "display_date": "September 3, 1861", "title": "Sheriff's Sale to H. S. Fulkerson", "text": "The Harrison County sheriff sells the Southern Pacific's road and franchises to H. S. Fulkerson for $7,500 to satisfy four judgments. On September 7, Fulkerson conveyed the property to a newly formed Southern Pacific company, J. S. Holman president, on condition that its board decide which stock of the old company would be admitted. The Supreme Court in 1882 traced the Texas and Pacific's title to this sale.", "source": "Stevenson v. Texas Railway Co., 105 U.S. 703 (1882), at 706, 708; Sheriff's deed to H. S. Fulkerson, Harrison County Deed Book T, p. 174; Fulkerson deed to Southern Pacific Rail Road Co., Sept. 7, 1861, Deed Book T, p. 546", "url": "https://csa-railroads.com/Essays/Orignial%20Docs/MISC/MISC,_SP_9-7-61.htm", "cats": ["railroad", "courts", "certificate"], "key": true, "status": "CORRECTED"}, {"src": [27, 28, 29], "date": "1863-08", "display_date": "Summer 1863", "title": "Track Moved Toward Shreveport Under Military Orders", "text": "Confederate Lt. Gen. E. Kirby Smith orders the Southern Pacific to connect with Shreveport as a military necessity and supplies 200 laborers. In August 1863 the company takes up the 12 miles from Swanson's Landing to Jonesville and relays the iron toward Shreveport, and it leases the Vicksburg, Shreveport and Texas line from Shreveport to the state line for twenty years.", "source": "Emilia Gay Means, \"East Texas and the Transcontinental Railroad,\" East Texas Historical Journal, Vol. 25, No. 2 (1987), Article 10", "url": "https://scholarworks.sfasu.edu/ethj/vol25/iss2/10/", "cats": ["railroad", "national", "marshall"], "key": false, "status": "CORRECTED"}, {"src": [30], "date": "1864-01-02", "display_date": "January 2, 1864", "title": "Dr. Jeptha Fowlkes Dies in Memphis", "text": "Dr. Jeptha Fowlkes, former president of the Southern Pacific and a Memphis banker and newspaper editor, dies in Memphis. He is buried in Winchester Cemetery.", "source": "Find a Grave Memorial 28052052; Winchester Cemetery listing, TNGenWeb (Shelby County)", "url": "", "cats": ["railroad"], "key": false, "status": "RECORD-ONLY"}, {"src": [31], "date": "1864-05", "display_date": "May 1864", "title": "Line Reaches Greenwood, Louisiana", "text": "By May 1864, eleven miles of track reach Greenwood, Louisiana, but the iron for the rest of the line to Shreveport is never delivered. The company reported losses of $20,174 in 1863, about $33,985 in 1864 and $37,800 in 1865. The line between Marshall and Shreveport was completed on July 28, 1866.", "source": "Emilia Gay Means, \"East Texas and the Transcontinental Railroad,\" East Texas Historical Journal, Vol. 25, No. 2 (1987), Article 10", "url": "https://scholarworks.sfasu.edu/ethj/vol25/iss2/10/", "cats": ["railroad", "national"], "key": false, "status": "CORRECTED"}, {"src": [32], "date": "1865-04-09", "display_date": "April 9, 1865", "title": "Lee Surrenders at Appomattox", "text": "Gen. Robert E. Lee surrenders the Army of Northern Virginia at Appomattox Court House, effectively ending the Civil War.", "source": "National Park Service, Appomattox Court House National Historical Park", "url": "https://www.nps.gov/apco/index.htm", "cats": ["national"], "key": false, "status": "VERIFIED"}, {"src": [33], "date": "1866-02-23", "display_date": "February 23, 1866", "title": "Stockholders Vote to Restore Paying Holders", "text": "Southern Pacific stockholders vote \"to restore to their former rights, all bona fide stockholders who shall comply with the Louisville Resolution of March 15, 1861.\"", "source": "DeBow's Review, After the War Series, Vol. 2, No. 2, p. 207 (1866)", "url": "", "cats": ["railroad", "certificate"], "key": false, "status": "RECORD-ONLY"}, {"src": [34, 35], "date": "1866-05-17", "display_date": "May 17, 1866", "title": "Hall Group Lends to the Railroad", "text": "According to the record in the Stevenson case, R. B. Hall and associates lend the Southern Pacific $100,000 to $150,000, secured by a mortgage. R. W. Loughery, a director, testified on August 27, 1873, that the company's books in this period were kept by Dr. A. T. Smith in Marshall. He said he had not heard of the mortgages or bonds until the complaint was filed.", "source": "Appellants' Transcript of Evidence, Stevenson v. Texas & Pacific Railway Co., Record pp. 281, 302; Loughery testimony, same record", "url": "", "cats": ["railroad", "courts"], "key": false, "status": "RECORD-ONLY"}, {"src": [36], "date": "1866-06-25", "display_date": "June 25, 1866", "title": "1866 Constitution Limits Sales of Franchises", "text": "Texas voters ratify the Constitution of 1866. Article VII, Section 36 repeals the railroad act \"approved 21st December, 1857,\" and provides that the franchise or corporate privileges of any incorporated company \"shall not be sold under judgments, except for the foreclosure of mortgages or liens, created in the manner prescribed by law.\"", "source": "Texas Constitution of 1866, Art. VII, Sec. 36 (Tarlton Law Library transcription); Handbook of Texas Online, \"Constitution of 1866\"", "url": "https://tarlton.law.utexas.edu/constitutions/texas-1866/article-7-general-provisions", "cats": ["courts", "railroad", "land"], "key": false, "status": "CORRECTED"}, {"src": [37], "date": "1867-05-16", "display_date": "May 16, 1867", "title": "Texas Demands Interest from the Railroad", "text": "The State of Texas writes to Southern Pacific president John M. Waskom that $43,625 in interest and $15,000 for the sinking fund are due, stating that \"no payments have been made by the Company on account of interest on Sinking Fund.\"", "source": "Governor James W. Throckmorton Papers, Briscoe Center for American History, University of Texas at Austin", "url": "", "cats": ["railroad"], "key": false, "status": "RECORD-ONLY"}, {"src": [38], "date": "1868-05-05", "display_date": "May 5, 1868", "title": "First Hall Sale in Harrison County", "text": "At a sheriff's sale in Harrison County, R. B. Hall buys the Southern Pacific's road, track and equipment for $2,150; the sale is recorded in Deed Book V, page 379. R. W. Loughery testified that he had been re-elected a director of the company that same day.", "source": "Harrison County Deed Records, Book V, p. 379; James Harper Starr land abstracts; Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (filed Nov. 2026), para. 29 (Book V, pp. 379 and 497 record the two 1868 sales)", "url": "", "cats": ["railroad", "courts", "marshall"], "key": true, "status": "CORRECTED"}, {"src": [39], "date": "1868-07-23", "display_date": "July 23, 1868", "title": "Judgment of $126,400 Against the Railroad", "text": "A Harrison County judgment for $126,400 is entered against the Southern Pacific in favor of R. B. Hall, William Garvin, Joseph Monks, Charles Cobb and Thomas Coleman.", "source": "Harrison County District Court records (July 23, 1868 judgment); James Harper Starr land abstracts", "url": "", "cats": ["courts", "railroad"], "key": false, "status": "RECORD-ONLY"}, {"src": [40], "date": "1868-09", "display_date": "September 1868", "title": "Company Attorney Advises Against the Sale", "text": "James Turner, attorney for the Southern Pacific, testified that two to three weeks before the October sale he advised R. B. Hall that it was not legal, because the 1866 Constitution had repealed the 1857 law. Col. Alexander Pope advised Hall to go ahead, and Hall proceeded.", "source": "Testimony in the record of Stevenson v. Texas & Pacific Railway Co., Record pp. 224 to 225; Appellants' Transcript of Evidence", "url": "", "cats": ["courts", "railroad"], "key": false, "status": "CORRECTED"}, {"src": [41], "date": "1868-10-06", "display_date": "October 6, 1868", "title": "Second Hall Sale: Charter and Franchises", "text": "Under the $126,400 judgment, R. B. Hall and more than 25 other buyers, including the City of Shreveport and John C. Brown, purchase the company's \"charter, franchises, privileges\" for $10,000 at a sheriff's sale in Caddo Parish, Louisiana. H. McKay of Marshall forbade the sale. The deed is recorded in Harrison County Deed Book V, page 497.", "source": "Harrison County Deed Records, Book V, p. 497; James Harper Starr land abstracts; Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (filed Nov. 2026), para. 29", "url": "", "cats": ["railroad", "courts"], "key": false, "status": "CORRECTED"}, {"src": [43], "date": "1869", "display_date": "1869", "title": "R. B. Hall Dies in Marshall", "text": "R. B. Hall dies suddenly in Marshall; the Marshall Republican wrote that he \"seemed in excellent health and was cheerful throughout the day.\" A statement in Union Pacific's own records later listed the estate of R. B. Hall for $74,502 of Southern Pacific stock outstanding on March 21, 1872.", "source": "Marshall (Texas) Republican, obituary of R. B. Hall (1869); Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (filed Nov. 2026), para. 26 (statement UP_003884)", "url": "", "cats": ["railroad", "marshall"], "key": false, "status": "CORRECTED"}, {"src": [44], "date": "1869-12-03", "display_date": "November 30 to December 3, 1869", "title": "1869 Constitution Ends New Land Grants", "text": "Texas voters ratify the Constitution of 1869. Article X, Section VI bars the legislature from granting lands \"to any person or persons\" except actual settlers, and Section VII declares railroad grant lands not yet alienated forfeited to the school fund. A constitutional amendment of 1874 allowed land grants again.", "source": "Texas Constitution of 1869, Art. X, Secs. VI and VII (Tarlton Law Library transcription); Handbook of Texas Online, \"Constitution of 1869\" and \"Railroads\"", "url": "https://tarlton.law.utexas.edu/constitutions/texas-1869/article-10-land-office", "cats": ["land", "courts"], "key": false, "status": "CORRECTED"}, {"src": [46], "date": "1870", "display_date": "1870", "title": "Marshall O. Roberts Buys Southern Pacific Stock", "text": "According to the record in the Stevenson case, New York financier Marshall O. Roberts buys $550,000 of new Southern Pacific stock.", "source": "Appellants' Transcript of Evidence, Stevenson v. Texas & Pacific Railway Co.", "url": "", "cats": ["railroad", "certificate"], "key": false, "status": "RECORD-ONLY"}, {"src": [47, 48], "date": "1870", "display_date": "1868 to 1870", "title": "James Harper Starr Settles in Marshall", "text": "James Harper Starr, former treasurer of the Republic of Texas and an authority on Texas land law, opens James H. Starr and Son, a land and banking agency in Marshall, in 1868 and moves his family there in 1870. His abstracts of Southern Pacific land titles include an August 1870 note on Survey No. 437: \"Hill could not survey. He was a mere Reconstruction appointee who could take the Test Oath.\"", "source": "Handbook of Texas Online, \"Starr, James Harper\"; James Harper Starr land abstracts, Survey No. 437 (Aug. 1870), Marshall", "url": "https://www.tshaonline.org/handbook/entries/starr-james-harper", "cats": ["marshall", "land"], "key": false, "status": "CORRECTED"}, {"src": [50, 52], "date": "1871", "display_date": "1871", "title": "Texas Authorizes Purchase of the Southern Pacific", "text": "The Texas Legislature recognizes the federal charter and authorizes the Texas Pacific to purchase the Southern Pacific Railroad Company and the Southern Trans-Continental Railway Company, both chartered by the state.", "source": "Handbook of Texas Online, \"Texas and Pacific Railway\"; Appellants' Transcript of Evidence, Stevenson v. Texas & Pacific Railway Co. (act of May 24, 1871)", "url": "https://www.tshaonline.org/handbook/entries/texas-and-pacific-railway", "cats": ["railroad", "courts"], "key": false, "status": "CORRECTED"}, {"src": [49], "date": "1871-03-03", "display_date": "March 3, 1871", "title": "Congress Charters the Texas Pacific Railroad", "text": "On the last day of the 41st Congress, Congress incorporates the Texas Pacific Railroad Company to build from Marshall, Texas, by way of El Paso to San Diego. Its charter let it buy and consolidate with railroads already chartered on its route. Marshall O. Roberts became its first president in April 1871, and Thomas A. Scott succeeded him on February 16, 1872. Section 20 of the charter made it unlawful for any director, alone or as a member of an incorporated or joint-stock company, to contract with the company for its construction. In December 1871 Scott bought Roberts's interest, and Roberts resigned as president in Scott's favor, a change not made public until February 1872.", "source": "Act of Mar. 3, 1871, ch. 122, 16 Stat. 573; Stevenson v. Texas Railway Co., 105 U.S. 703 (1882), at 704; Handbook of Texas Online, \"Texas and Pacific Railway\"; Texas and Pacific Railway, \"Oxteams to Eagles\" (company history, list of presidents); Christopher T. Baer, \"PRR Chronology, 1871,\" Pennsylvania Railroad Technical and Historical Society", "url": "https://www.govinfo.gov/link/statute/16/573", "cats": ["railroad", "national"], "key": false, "status": "CORRECTED"}, {"src": "app-42, app-38, app-40, app-41", "date": "1871-03-22", "display_date": "March 22 to May 26, 1871", "title": "A Run of Pennsylvania Companies Is Chartered", "text": "In the same weeks the Domain Land Company was chartered, R. D. Barclay and S. S. Moon were named as incorporators of a series of other Pennsylvania companies with broad powers, among them the Overland Contract, Empire Contract, South Improvement, Granite Improvement, Madison Improvement, Washington Improvement and Duquesne Contract companies. Pennsylvania Railroad historian Christopher T. Baer lists them as \"Tom Scott\" companies. Some later became lasting concerns, such as the Southern Railway Security Company and the Philadelphia Company.", "source": "Christopher T. Baer, \"PRR Chronology, 1871,\" Pennsylvania Railroad Technical and Historical Society (entries of Mar. 22, Apr. 5, May 5, 6, 9 and 26, 1871, citing Pennsylvania session laws and ICC records)", "url": "http://www.prrths.com/newprr_files/Hagley/PRR1871.pdf", "cats": ["construction-co"], "key": false, "status": "VERIFIED"}, {"src": "app-45, app-44", "date": "1871-04-15", "display_date": "April 15 and May 23, 1871", "title": "The Texas Pacific Railroad Organizes in New York", "text": "Seventy-five of the 123 incorporators named in the federal charter met in New York to organize the company, and on Thomas A. Scott's motion Marshall O. Roberts was allowed to subscribe for 11,000 of its 20,000 shares. On May 23, 1871, the stockholders elected a board, which chose Roberts president and Edwards Pierrepont treasurer, put Scott, Pierrepont and William T. Walters on the executive committee, and named Gen. Grenville M. Dodge chief engineer.", "source": "Christopher T. Baer, \"PRR Chronology, 1871,\" Pennsylvania Railroad Technical and Historical Society (Apr. 15 and May 23, 1871 entries, citing the company's annual report, J. P. Green pamphlets, American Railroad Journal and New York Times)", "url": "http://www.prrths.com/newprr_files/Hagley/PRR1871.pdf", "cats": ["railroad"], "key": false, "status": "VERIFIED"}, {"src": [45, 51], "date": "1871-05-05", "display_date": "May 5, 1871", "title": "Pennsylvania Charters the Domain Land Company", "text": "The Pennsylvania General Assembly incorporates the Domain Land Company by special act, with a supplement on May 19, 1871. The act gave it the powers of the National Land and Improvement Company and of the Pennsylvania Company, which the legislature had incorporated on April 7, 1870. In June 1872 the Domain Land Company became the California and Texas Railway Construction Company.", "source": "Commonwealth ex rel. Elkin v. California and Texas Railway Construction Co., 5 Dauphin County Reports 181 (C.P. Dauphin Cnty., Pa. 1902), at 190 to 191 (letters patent reciting the acts); Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (filed Nov. 2026), para. 22", "url": "", "cats": ["construction-co"], "key": false, "status": "CORRECTED"}, {"src": [53], "date": "1871-09-06", "display_date": "September 6, 1871", "title": "V. K. Stevenson Sues the Texas and Pacific", "text": "Claiming under the 1860 mortgages, V. K. Stevenson sues the Texas and Pacific in the U.S. Circuit Court at Tyler, saying the original bonds had sunk in the Mississippi River aboard a steamer bound for Memphis. F. B. Sexton served as counsel for the railroad in the case.", "source": "V. K. Stevenson v. Texas & Pacific Railway Co., Nos. 68 and 69, U.S. Circuit Court, W.D. Tex., Opinion and Final Order (certified copy); Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (filed Nov. 2026), para. 55 (Sexton as counsel for the Texas and Pacific in the Stevenson litigation)", "url": "", "cats": ["courts", "railroad"], "key": false, "status": "CORRECTED"}, {"src": [54], "date": "1872-03-21", "display_date": "March 21, 1872", "title": "The Texas Pacific Buys the Southern Pacific", "text": "By a deed dated March 21, 1872, the Southern Pacific conveys its franchises, property, bonds and \"Stocks\" to the Texas Pacific Railroad Company for $3 million in seven percent land grant bonds, with Thomas A. Scott signing as president of both companies. The deed is recorded in Harrison County Deed Book Z, pages 121 and 122. A statement in Union Pacific's own records lists $1,250,000 of Southern Pacific stock outstanding that day, $625,600 of it in Scott's name.", "source": "Deed of Mar. 21, 1872, Harrison County Deed Book Z, pp. 121 to 122 (certified copy at UP_003876 to UP_003880); statement UP_003884; Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (filed Nov. 2026), paras. 21 and 26; Stevenson v. Texas Railway Co., 105 U.S. 703 (1882), at 704", "url": "https://www.govinfo.gov/content/pkg/USREPORTS-105/pdf/USREPORTS-105-703.pdf", "cats": ["railroad", "certificate"], "key": true, "status": "CORRECTED"}, {"src": [56], "date": "1872-05-02", "display_date": "May 2, 1872", "title": "Renamed the Texas and Pacific Railway Company", "text": "Congress changes the company's name from the Texas Pacific Railroad Company to the Texas and Pacific Railway Company, with all the rights and franchises of the original charter.", "source": "Act of May 2, 1872, ch. 132, 17 Stat. 59; Handbook of Texas Online, \"Texas and Pacific Railway\"", "url": "https://www.govinfo.gov/link/statute/17/59", "cats": ["railroad", "national"], "key": false, "status": "CORRECTED"}, {"src": "app-56", "date": "1872-05-22", "display_date": "May 22, 1872", "title": "Scott Offers Carnegie a Construction Company Share", "text": "Thomas A. Scott offered Andrew Carnegie one of forty $250,000 shares in the California and Texas Railway Construction Company and asked whether J. S. Morgan and Company or Sulzbach Brothers would market Texas and Pacific bonds. Carnegie took one share and J. Edgar Thomson took two, and Scott said they would have to pay only 10 percent of the price. In November 1872 Thomson told Carnegie he had no money to invest, his funds having gone into the construction company and a Mexican railway venture.", "source": "Christopher T. Baer, \"PRR Chronology, 1872,\" Pennsylvania Railroad Technical and Historical Society (May 22 and Nov. 14, 1872 entries, citing David Nasaw, Andrew Carnegie (2006))", "url": "http://www.prrths.com/newprr_files/Hagley/PRR1872.pdf", "cats": ["construction-co"], "key": false, "status": "VERIFIED"}, {"src": "app-55, app-54", "date": "1872-06-01", "display_date": "June 1 and July 1, 1872", "title": "The Texas and Pacific's 1872 Mortgages", "text": "On June 1, 1872, the Texas and Pacific executed a construction mortgage to J. Edgar Thomson and S. M. Felton as trustees, for bonds at $40,000 a mile secured by a first mortgage on its federal land grant of about 15 million acres. On July 1 it executed a $20 million land grant mortgage to Edwards Pierrepont and William T. Walters, figured at $1.50 an acre, under which only $4 million in bonds was issued.", "source": "Christopher T. Baer, \"PRR Chronology, 1872,\" Pennsylvania Railroad Technical and Historical Society (June 1 and July 1, 1872 entries, citing a J. P. Green pamphlet and Poor's Manual)", "url": "http://www.prrths.com/newprr_files/Hagley/PRR1872.pdf", "cats": ["land", "railroad"], "key": false, "status": "VERIFIED"}, {"src": [57], "date": "1872-06-17", "display_date": "June 17, 1872", "title": "Domain Land Company Becomes the Construction Company", "text": "The Domain Land Company's stockholders change its name to the California and Texas Railway Construction Company, and on June 19, 1872, Pennsylvania Governor John W. Geary issues letters patent to its subscribers, R. D. Barclay, John P. Green and S. S. Moon. A Pennsylvania court found in 1902 that the company had organized lawfully and kept a continuous organization, transacted business and paid taxes from 1872 forward.", "source": "Commonwealth ex rel. Elkin v. California and Texas Railway Construction Co., 5 Dauphin County Reports 181 (C.P. Dauphin Cnty., Pa. 1902), at 190 to 191; Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (filed Nov. 2026), para. 22", "url": "", "cats": ["construction-co"], "key": true, "status": "CORRECTED"}, {"src": [58, 59], "date": "1872-06-22", "display_date": "June 22 to 26, 1872", "title": "Marshall's agreement with Thomas A. Scott", "text": "At Mrs. King's Hotel in Marshall on June 22, Scott reached terms with a city committee of F. B. Sexton, E. D. Blanch and M. D. Ector, which put them in writing on June 26: Harrison County would donate $300,000 in bonds and the city 66 acres, and the Texas and Pacific would \"permanently establish its eastern terminus and Texas office\" at Marshall and build its main machine shops and car works there. Scott accepted by letter of July 16, 1872. The county issued the bonds, and the city bought the 66 acres for $60,000 and deeded them to the railway.", "source": "Texas & Pacific Railway Co. v. City of Marshall, 136 U.S. 393, 394 to 396 (1890) (letters of June 26 and July 16, 1872, set out as exhibits to the city's bill)", "url": "https://www.govinfo.gov/content/pkg/USREPORTS-136/pdf/USREPORTS-136-393.pdf", "cats": ["railroad", "marshall"], "key": true, "status": "CORRECTED"}, {"src": [60, 61], "date": "1872-08-06", "display_date": "August 6, 1872", "title": "Construction company signs the Texas and Pacific contract", "text": "On August 5, 1872, the stockholders of the California and Texas Railway Construction Company, a Pennsylvania corporation, raised its capital from $100,000 to $10,000,000. The next day it contracted with the Texas and Pacific to build and equip several hundred miles of the road, with no pay until 100 continuous miles west of Longview were finished. It was to be paid in the railway's bonds and stock.", "source": "Commonwealth ex rel. Elkin v. California and Texas Railway Construction Co., 5 Dauphin County Reports 181 (C.P. Dauphin Cnty., Pa. 1902), at 191 to 192; Nebraska fraud complaint (Douglas County, 2026), paragraph 23", "url": "", "cats": ["construction-co", "railroad"], "key": false, "status": "CORRECTED"}, {"src": [62], "date": "1872-09-11", "display_date": "September 11, 1872", "title": "Marshall committee writes to Starr's land agency", "text": "E. D. Blanch and M. D. Ector, two of the three Marshall committee members who had made the terminus agreement with Scott, wrote to James H. Starr and Son, the Marshall land and banking agency, about powers of attorney.", "source": "James Harper Starr Papers, Dolph Briscoe Center for American History, University of Texas at Austin (letter of Sept. 11, 1872); committee membership from 136 U.S. 393, 396 (1890)", "url": "", "cats": ["marshall"], "key": false, "status": "RECORD-ONLY"}, {"src": [63], "date": "1872-10", "display_date": "October 1872", "title": "Construction begins", "text": "The California and Texas Railway Construction Company began building the Texas and Pacific lines in October 1872. By October 19 the company reported the line under contract at points between Texarkana and Fort Worth and between Longview and Fort Worth, with 10,000 tons of English iron bought.", "source": "George C. Werner, \"Texas and Pacific Railway,\" Handbook of Texas Online (TSHA); Commonwealth ex rel. Elkin v. California and Texas Railway Construction Co., 5 Dauphin County Reports 181 (C.P. Dauphin Cnty., Pa. 1902), at 192 to 193", "url": "https://www.tshaonline.org/handbook/entries/texas-and-pacific-railway", "cats": ["railroad", "construction-co"], "key": false, "status": "VERIFIED"}, {"src": "app-50, app-48", "date": "1873-03-03", "display_date": "February 5 to March 3, 1873", "title": "Congress Lets a Texas and Pacific Bill Die", "text": "On February 5, 1873, Senator John Scott of Pennsylvania introduced a bill, S. 1537, to let the Texas and Pacific connect or consolidate with railroads in California, including the California-based Southern Pacific, to reach San Francisco. The Senate passed a substitute on March 1, but on March 3, the last day of the 42nd Congress, the House failed to pass it.", "source": "Christopher T. Baer, \"PRR Chronology, 1873,\" Pennsylvania Railroad Technical and Historical Society (Feb. 5, Mar. 1 and Mar. 3, 1873 entries, citing the Congressional Globe)", "url": "http://www.prrths.com/newprr_files/Hagley/PRR1873.pdf", "cats": ["national", "railroad"], "key": false, "status": "CORRECTED"}, {"src": [64], "date": "1873-06-04", "display_date": "June 4, 1873", "title": "\"Southern Pacific Railway stock converted\"", "text": "At the construction company's annual meeting on June 4, 1873, its treasurer reported that $1,068,947.57 of the capital subscribed was \"Southern Pacific Railway stock converted,\" listed separately from $97,650 of \"Texas and Pacific stock converted.\" A report to its directors on March 21, 1873, had listed \"Full paid stock (S. P.)\" of $1,249,152. The 2026 fraud complaint filed by John Stephen Thorne alleges that this was stock of the Southern Pacific Railroad Company of Texas, and that Union Pacific's 2011 answer left this conversion out.", "source": "Commonwealth ex rel. Elkin v. California and Texas Railway Construction Co., 5 Dauphin County Reports 181 (C.P. Dauphin Cnty., Pa. 1902), at 194 and 196; Nebraska fraud complaint (2026), paragraphs 23 and 34", "url": "", "cats": ["construction-co", "certificate", "answers"], "key": true, "status": "CORRECTED"}, {"src": [66], "date": "1873-07-01", "display_date": "July 1, 1873", "title": "Longview to Dallas opens", "text": "The 125 miles of Texas and Pacific track between Longview and Dallas were placed in service on July 1, 1873. Under the construction contract, the builder was to receive no pay until 100 continuous miles west of Longview were finished.", "source": "Werner, \"Texas and Pacific Railway,\" Handbook of Texas Online; Commonwealth ex rel. Elkin v. California and Texas Railway Construction Co., 5 Dauphin County Reports 181 (C.P. Dauphin Cnty., Pa. 1902), at 192", "url": "https://www.tshaonline.org/handbook/entries/texas-and-pacific-railway", "cats": ["railroad"], "key": false, "status": "CORRECTED"}, {"src": [67], "date": "1873-09-18", "display_date": "September 18, 1873", "title": "Panic of 1873", "text": "Jay Cooke and Company failed on September 18, 1873. The construction company's president later reported that a sale of $10,000,000 of its bonds in London was ready to be signed on the day the news arrived, and the sale fell through. On October 16, 1873, with 226 miles built and a yellow fever outbreak preventing inspection, the two companies cancelled the unfinished part of the construction contract.", "source": "Commonwealth ex rel. Elkin v. California and Texas Railway Construction Co., 5 Dauphin County Reports 181 (C.P. Dauphin Cnty., Pa. 1902), at 197 to 199; Werner, \"Texas and Pacific Railway,\" Handbook of Texas Online", "url": "https://www.tshaonline.org/handbook/entries/texas-and-pacific-railway", "cats": ["national", "construction-co", "railroad"], "key": false, "status": "CORRECTED"}, {"src": [68], "date": "1873-11-04", "display_date": "November 4, 1873", "title": "\"Tom Scott's Credit Mobilier\"", "text": "The Philadelphia Evening Telegraph reported that the California and Texas Railway Construction Company, which it called \"Tom Scott's Credit Mobilier,\" could not meet its obligations and that more than $300,000 of its paper had \"went to protest.\" The paper put its notes maturing within 90 days at $4.5 million and its total debt near $7 million.", "source": "Evening Telegraph (Philadelphia), Nov. 4, 1873, p. 1", "url": "", "cats": ["construction-co", "national"], "key": false, "status": "RECORD-ONLY"}, {"src": [69], "date": "1873-12-28", "display_date": "December 28, 1873", "title": "Marshall to Texarkana opens", "text": "The 74 miles of Texas and Pacific track from Marshall to Texarkana opened for regular service on December 28, 1873.", "source": "Werner, \"Texas and Pacific Railway,\" Handbook of Texas Online", "url": "https://www.tshaonline.org/handbook/entries/texas-and-pacific-railway", "cats": ["railroad", "marshall"], "key": false, "status": "VERIFIED"}, {"src": [70], "date": "1874", "display_date": "1874", "title": "L. S. Thorne joins the Texas and Pacific", "text": "L. S. Thorne entered the service of the Texas and Pacific as trainmaster. He soon became its first master of transportation and then district superintendent of transportation.", "source": "Encyclopedia of Texas, Vol. III (biographical entry for L. S. Thorne)", "url": "", "cats": ["certificate", "railroad"], "key": false, "status": "RECORD-ONLY"}, {"src": [74], "date": "1875", "display_date": "1875", "title": "Loughery starts the Tri-Weekly Herald", "text": "Robert W. Loughery, long the editor of the Marshall Texas Republican, began the Marshall Tri-Weekly Herald in 1875 as its editor.", "source": "Max S. Lale, \"Loughery, Robert W.,\" Handbook of Texas Online (TSHA)", "url": "https://www.tshaonline.org/handbook/entries/loughery-robert-w", "cats": ["marshall"], "key": false, "status": "VERIFIED"}, {"src": [71], "date": "1875-03-27", "display_date": "March 27, 1875", "title": "Construction contract adjusted", "text": "The construction company and the Texas and Pacific adjusted their contract on March 27, 1875, and made a further agreement on January 2, 1880, settling pay for 110 miles of road the company had partly built. A Pennsylvania court later found that after the Panic of 1873 the company could not finish its contract or readily dispose of the securities it had received.", "source": "Commonwealth ex rel. Elkin v. California and Texas Railway Construction Co., 5 Dauphin County Reports 181 (C.P. Dauphin Cnty., Pa. 1902), at 200", "url": "", "cats": ["construction-co"], "key": false, "status": "VERIFIED"}, {"src": [72, 73], "date": "1875-05-15", "display_date": "March 29 and May 15, 1875", "title": "The Income and Land Grant Mortgage", "text": "On March 29, 1875, Texas and Pacific stockholders authorized 8,908 Income and Land Grant bonds of $1,000 each, secured by a first mortgage on the company's Texas lands, including lands earned under the charters of the Southern Pacific Railroad Company and two other predecessors, estimated at about 7,600,000 acres. The mortgage, dated May 15, 1875, ran to trustees W. T. Walters and George D. Krumbhaar. Interest could be paid in scrip instead of cash when net earnings fell short.", "source": "Texas & Pacific Ry. Co. v. Marlor, 123 U.S. 687, 692 to 695 (1887)", "url": "https://tile.loc.gov/storage-services/service/ll/usrep/usrep123/usrep123687/usrep123687.pdf", "cats": ["land", "railroad"], "key": true, "status": "VERIFIED"}, {"src": [77], "date": "1876", "display_date": "1876", "title": "John C. Brown joins the Texas and Pacific", "text": "John C. Brown, former Confederate general and governor of Tennessee, who supported Thomas A. Scott's southern transcontinental plan, joined the Texas and Pacific as a vice president in 1876.", "source": "Tennessee State Library and Archives biography of John C. Brown, as summarized in \"John C. Brown,\" Wikipedia", "url": "", "cats": ["railroad"], "key": false, "status": "VERIFIED"}, {"src": [80], "date": "1876-01-29", "display_date": "January 29, 1876", "title": "Huntington on Scott's lobbying", "text": "Collis P. Huntington of the rival Central Pacific, fighting Scott's Texas and Pacific bill in Congress, wrote to his partner David Colton that Scott \"switched Senator Spencer of Alabama and Walker of Virginia this week, but you know they can be switched back with the proper arrangements when they are wanted.\"", "source": "Huntington to Colton, letter No. 110, New York, Jan. 29, 1876, in J. Hampton Moore, How Members of Congress Are Bribed (1895), Project Gutenberg eBook #3316", "url": "https://www.gutenberg.org/ebooks/3316", "cats": ["national", "railroad"], "key": false, "status": "CORRECTED"}, {"src": [75], "date": "1876-03-23", "display_date": "March 23, 1876", "title": "Supplemental mortgage east of Fort Worth", "text": "A supplemental mortgage to the same trustees, Walters and Krumbhaar, added the Texas and Pacific's lines east of Fort Worth, \"five hundred and twenty-four miles of railroad nearly completed,\" running from the Louisiana line through Marshall and Dallas to Fort Worth, with branches through Jefferson, Texarkana, Clarksville, Paris, Bonham and Sherman. In 1888 the trustees of these two mortgages, then Charles E. Satterlee and George J. Gould, joined in conveying the lands to Charles J. Canda, Simeon J. Drake and William Strauss.", "source": "Texas & Pacific Ry. Co. v. Marlor, 123 U.S. 687, 695 to 696 (1887); Texas Pacific Land Trust Declaration of Trust (Feb. 1, 1888), as filed with the SEC", "url": "https://tile.loc.gov/storage-services/service/ll/usrep/usrep123/usrep123687/usrep123687.pdf", "cats": ["land", "railroad"], "key": false, "status": "CORRECTED"}, {"src": [76], "date": "1876-06-07", "display_date": "June 7, 1876", "title": "Scott agrees to settle Dodge's claim", "text": "Writing from Philadelphia, Frank S. Bond told Gen. Grenville M. Dodge that his claim against the construction company came to $107,801.33, and that \"in talking over the matter today with Mr. Scott he agreed to liquidate this indebtedness.\"", "source": "Letter, Frank S. Bond to Gen. G. M. Dodge, June 7, 1876, Grenville M. Dodge Papers", "url": "", "cats": ["construction-co"], "key": false, "status": "RECORD-ONLY"}, {"src": [79], "date": "1876-07-19", "display_date": "July 19, 1876", "title": "Rails reach Fort Worth", "text": "The Texas and Pacific line from Eagle Ford was extended to Fort Worth on July 19, 1876. With the Brookston to Texarkana line opened that August 11, the company had 444 miles of line, far short of its chartered goal of San Diego.", "source": "Werner, \"Texas and Pacific Railway,\" Handbook of Texas Online", "url": "https://www.tshaonline.org/handbook/entries/texas-and-pacific-railway", "cats": ["railroad"], "key": false, "status": "VERIFIED"}, {"src": [82, 83], "date": "1877-03-05", "display_date": "March 5, 1877", "title": "Hayes takes office; Compromise of 1877", "text": "Rutherford B. Hayes was inaugurated after an Electoral Commission gave him all 20 disputed electoral votes, 185 to 184. Historian C. Vann Woodward argued that the settlement included withdrawal of federal troops from the South, a Southern Democrat in the cabinet (David M. Key of Tennessee became Postmaster General), and support for Scott's Texas and Pacific; other historians, such as Allan Peskin, dispute that a bargain was made. Hayes withdrew the last troops from Louisiana in April 1877, but the federal subsidy for Scott's road never passed.", "source": "C. Vann Woodward, Reunion and Reaction (1951); Allan Peskin, \"Was There a Compromise of 1877?\" Journal of American History 60 (1973): 63 to 75; Werner, \"Texas and Pacific Railway,\" Handbook of Texas Online", "url": "", "cats": ["national"], "key": false, "status": "CORRECTED"}, {"src": [85, 65], "date": "1878-06-17", "display_date": "June 17, 1878", "title": "Judge Du Val rules on the Stevenson bonds", "text": "In a suit by V. K. Stevenson and other holders of bonds under two 1860 mortgages of the reorganized Southern Pacific, U.S. Judge Thomas H. Du Val at Tyler ruled against the bondholders, finding that entries in the company's Book No. 2 authorizing the bonds had been \"falsely and fraudulently interpolated.\" The company's record books were ordered sent to the Supreme Court in Washington.", "source": "Stevenson v. Texas & Pacific Railway Co., Nos. 68 and 69, U.S. Circuit Court, Western District of Texas, at Tyler, Opinion and Final Order (June 17, 1878), certified copy in JS's records; affirmed, Stevenson v. Texas Railway Co., 105 U.S. 703 (1882)", "url": "", "cats": ["courts", "railroad"], "key": false, "status": "RECORD-ONLY"}, {"src": [86], "date": "1878-10-24", "display_date": "October 24, 1878", "title": "John C. Brown's letter to the South", "text": "Texas and Pacific vice president John C. Brown published \"A Letter to the People of the South\" from Pulaski, Tennessee, urging Congress to back the road with government-guaranteed bonds and offering its land grants in New Mexico, Arizona and California as security.", "source": "Texas and Pacific Railway, A Letter from Jno. C. Brown, Vice-President, To the People of the South (Pulaski, Tenn., 1878), HathiTrust Digital Library", "url": "", "cats": ["railroad", "national"], "key": false, "status": "RECORD-ONLY"}, {"src": [87], "date": "1878-11-17", "display_date": "November 17, 1878", "title": "Fire destroys the federal court records at Tyler", "text": "Fire destroyed the records of the federal court at Tyler on November 17, 1878. Judge Du Val, who had decided the Stevenson case there that June, wrote in his diary that \"no doubt seems to be entertained, but that the fire was designed to destroy the Court room, and break up the business of the Court.\"", "source": "National Archives at Fort Worth, finding aid for Record Group 21, Texas courts (\"Fires destroyed the records of ... the Tyler court on November 17, 1878\"); Thomas H. Du Val diary, Nov. 18, 1878, Du Val Papers, Briscoe Center for American History", "url": "https://www.archives.gov/fort-worth/finding-aids/rg021-texas-courts", "cats": ["courts"], "key": false, "status": "CORRECTED"}, {"src": [88, 89, 90], "date": "1879", "display_date": "Fall 1879", "title": "Jay Gould's syndicate takes over", "text": "\"In the fall of 1879, Jay Gould organized a syndicate to acquire an interest in and to complete the Texas and Pacific,\" with Gen. Grenville M. Dodge again in charge of construction. Gould and his associates took control of the road from Scott's management.", "source": "Werner, \"Texas and Pacific Railway,\" Handbook of Texas Online", "url": "https://www.tshaonline.org/handbook/entries/texas-and-pacific-railway", "cats": ["railroad"], "key": false, "status": "CORRECTED"}, {"src": [92], "date": "1880", "display_date": "c. 1880 to 1883", "title": "Thorne builds track for the Southern Pacific", "text": "L. S. Thorne left Marshall for about three years to serve the (California) Southern Pacific as superintendent of transportation and construction, laying track east from Yuma, Arizona, toward the Texas lines. He then returned to Marshall.", "source": "Encyclopedia of Texas, Vol. III (biographical entry for L. S. Thorne)", "url": "", "cats": ["certificate", "railroad"], "key": false, "status": "RECORD-ONLY"}, {"src": [93], "date": "1880-08-10", "display_date": "August 10, 1880", "title": "Construction company cancels most of its stock", "text": "The construction company's stockholders surrendered for cancellation all but $100,000 of its capital stock and fixed its capital at 2,000 shares of $50. The company kept its organization, held meetings and paid Pennsylvania taxes through 1900, and in October 2025 the Pennsylvania Department of State still listed it as an active corporation, Entity No. 53037.", "source": "Commonwealth ex rel. Elkin v. California and Texas Railway Construction Co., 5 Dauphin County Reports 181 (C.P. Dauphin Cnty., Pa. 1902), at 200 to 201; Nebraska fraud complaint (2026), paragraphs 45 and 54", "url": "", "cats": ["construction-co"], "key": false, "status": "CORRECTED"}, {"src": [95], "date": "1881-05-21", "display_date": "May 21, 1881", "title": "Thomas A. Scott dies", "text": "Thomas A. Scott, who had led the Texas and Pacific through the 1870s, died in Philadelphia on May 21, 1881. He had suffered a stroke in 1878, and the Gould syndicate had taken over the road in 1879 and 1880.", "source": "\"Thomas A. Scott,\" Wikipedia (citing James A. Ward); Werner, \"Texas and Pacific Railway,\" Handbook of Texas Online", "url": "", "cats": ["railroad"], "key": false, "status": "CORRECTED"}, {"src": [94], "date": "1881-06-13", "display_date": "June 13, 1881", "title": "Pennsylvania Supreme Court on who held T&P stock", "text": "In a Pennsylvania tax case, the state Supreme Court held that the Texas and Pacific did not need a license for its Philadelphia office because \"nearly all of its actual capital stock was held and controlled by the California and Texas Construction Company, a Pennsylvania corporation,\" which paid Pennsylvania tax.", "source": "Commonwealth v. Texas & Pacific Railroad Co., 98 Pa. 90, 100 to 101 (1881) (decided June 13, 1881)", "url": "https://hallapproved.com/pa/cases/supreme/1881/6368028/", "cats": ["courts", "construction-co"], "key": true, "status": "CORRECTED"}, {"src": [91, 96], "date": "1881-12-16", "display_date": "December 16, 1881", "title": "Rails reach Sierra Blanca", "text": "Track laying west from Fort Worth began April 1, 1880, and reached Sierra Blanca, 520 miles west, on December 16, 1881. Under the Gould and Huntington agreement of November 26, 1881, the Texas and Pacific stopped there and shared the Southern Pacific's track to El Paso, so it never reached San Diego. From 1873 to 1881 it built 972 miles of track but received land only for its lines east of Fort Worth, 5,173,120 acres.", "source": "Werner, \"Texas and Pacific Railway,\" Handbook of Texas Online", "url": "https://www.tshaonline.org/handbook/entries/texas-and-pacific-railway", "cats": ["railroad", "land"], "key": false, "status": "CORRECTED"}, {"src": [98], "date": "1882-05-08", "display_date": "May 8, 1882", "title": "Supreme Court decides Stevenson", "text": "The U.S. Supreme Court affirmed the decree against the Stevenson bondholders on a single question: the 1861 sheriff's sale to H. S. Fulkerson came ahead of the unrecorded 1860 mortgages. It stated that the Southern Pacific \"became consolidated with\" the Texas and Pacific on March 21, 1872, and traced the railway's title \"through its purchase from and consolidation with the Southern Pacific Railroad Company, which duly succeeded to the title of Fulkerson.\" The opinion does not discuss the 1868 Hall sales.", "source": "Stevenson v. Texas Railway Co., 105 U.S. 703, 704 to 708 (1882) (argued April 13, 14 and 17; decided May 8, 1882)", "url": "https://tile.loc.gov/storage-services/service/ll/usrep/usrep105/usrep105703/usrep105703.pdf", "cats": ["courts", "certificate"], "key": true, "status": "CORRECTED"}, {"src": [97], "date": "1882-05-23", "display_date": "May 23, 1882", "title": "Thorne named division superintendent", "text": "The Marshall Tri-Weekly Herald announced that L. S. (Charley) Thorne had been appointed division superintendent of the Texas and Pacific's transcontinental division, succeeding Scott Noble, who resigned, and that Thorne would make his home in Marshall.", "source": "Marshall Tri-Weekly Herald, May 23, 1882, p. 3", "url": "", "cats": ["certificate", "marshall"], "key": false, "status": "RECORD-ONLY"}, {"src": [99, 100, 101], "date": "1882-09-30", "display_date": "1882 to 1884", "title": "Texas and Pacific land reports", "text": "The Texas and Pacific's reports to the Texas Comptroller showed 921,534 acres sold and 4,434,818 acres unsold on September 30, 1882, with capital stock of $34,161,700 and no dividends paid. Unsold land stood at 4,414,818 acres a year later and at 3,843,611 acres on September 30, 1884.", "source": "Texas and Pacific Railway annual reports to the Texas Comptroller, Sept. 30, 1882, 1883 and 1884, Texas State Library and Archives", "url": "", "cats": ["land", "railroad"], "key": false, "status": "RECORD-ONLY"}, {"src": [102], "date": "1885-02-28", "display_date": "February 28, 1885", "title": "Congress forfeits the federal land grant", "text": "Congress declared forfeited all lands granted to the Texas Pacific Railroad Company under its 1871 federal charter and restored them to the public domain \"as though said grant had never been made.\" The federal grant covered the route west of Texas, through New Mexico, Arizona and California.", "source": "Act of Feb. 28, 1885, ch. 265, 23 Stat. 337; Werner, \"Texas and Pacific Railway,\" Handbook of Texas Online (federal grant)", "url": "https://www.govinfo.gov/link/statute/23/337", "cats": ["courts", "land", "national"], "key": false, "status": "CORRECTED"}, {"src": [104], "date": "1885-12", "display_date": "December 1885", "title": "Marshall goes to court to hold the shops", "text": "When the Texas and Pacific moved offices and parts of its shops away from Marshall, the city sued in the state district court to enforce the 1872 agreement. The case was removed to federal court, which ordered the company not to remove any more of its offices; James Turner was among the city's lawyers. In 1890 the U.S. Supreme Court reversed that decree, holding that the company had kept its promise by maintaining the terminus, offices and shops at Marshall for some years.", "source": "Texas & Pacific Railway Co. v. City of Marshall, 136 U.S. 393, 397 to 400 (1890); Marshall Messenger, Dec. 1885", "url": "https://tile.loc.gov/storage-services/service/ll/usrep/usrep136/usrep136393/usrep136393.pdf", "cats": ["marshall", "courts"], "key": false, "status": "CORRECTED"}, {"src": [103, 105], "date": "1885-12-15", "display_date": "December 15, 1885", "title": "Texas and Pacific placed in receivership", "text": "The U.S. Circuit Court for the Eastern District of Louisiana appointed John C. Brown receiver of the Texas and Pacific and all its property in Texas and Louisiana. He qualified on December 16, 1885, and with Lionel A. Sheldon ran the road until the receivership ended June 1, 1888.", "source": "Texas & Pacific Railway Co. v. Johnson, 151 U.S. 81, 83 to 84 (1894); Missouri Bureau of Labor Statistics, The Official History of the Great Strike of 1886 on the Southwestern Railway System (1886), pp. 9 to 10", "url": "https://www.govinfo.gov/content/pkg/USREPORTS-151/pdf/USREPORTS-151-81.pdf", "cats": ["railroad", "courts"], "key": false, "status": "CORRECTED"}, {"src": [106], "date": "1886-01-15", "display_date": "January 15, 1886", "title": "Egbert named superintendent", "text": "The Marshall Messenger reported that \"Mr. Augustus A. Egbert, late of the Union Pacific, will succeed Mr. Cumming as superintendent of the Texas & Pacific.\"", "source": "Marshall Messenger, Jan. 15, 1886, p. 3", "url": "", "cats": ["marshall", "railroad"], "key": false, "status": "RECORD-ONLY"}, {"src": [107], "date": "1886-01-18", "display_date": "January 18, 1886", "title": "Superintendent's office moved to Dallas", "text": "The Marshall Messenger reported that on the night of January 18, between 11 p.m. and 4 a.m., the general superintendent's office at Marshall was \"stripped of its furniture, papers, etc.\" by Texas and Pacific officials, an act it said was \"in violation of the injunction of our District Court.\" The paper said the furniture, books and papers were \"now in Dallas.\"", "source": "Marshall Messenger, Jan. 22, 1886, p. 3", "url": "", "cats": ["marshall"], "key": false, "status": "RECORD-ONLY"}, {"src": [108], "date": "1886-02-18", "display_date": "February 18, 1886", "title": "Foreman C. A. Hall discharged", "text": "C. A. Hall, a foreman in the Texas and Pacific car shops at Marshall and a Knight of Labor, was discharged by order of department chief J. A. Crosby. The Knights said he was let go for attending a union meeting he had permission to attend; Crosby said it was for incompetency.", "source": "Missouri Bureau of Labor Statistics, The Official History of the Great Strike of 1886 on the Southwestern Railway System (1886), pp. 8 and 10", "url": "https://archive.org/details/officialhistoryo00miss", "cats": ["marshall", "railroad"], "key": false, "status": "CORRECTED"}, {"src": [109], "date": "1886-03-01", "display_date": "March 1, 1886", "title": "The Great Southwest Strike begins at Marshall", "text": "At 3 p.m. on March 1, 1886, \"the shopmen at Marshall laid down their tools and went out in a body,\" with the shopmen at Fort Worth and Dallas, in a strike called by Martin Irons of the Knights of Labor. It spread across Jay Gould's southwestern lines. Gould's companies hired Pinkerton detectives, and Texas Governor John Ireland sent state militia and Texas Rangers to Fort Worth.", "source": "Missouri Bureau of Labor Statistics, Official History of the Great Strike of 1886, p. 10; James C. Maroney, \"Great Southwest Strike,\" Handbook of Texas Online (TSHA)", "url": "https://archive.org/details/officialhistoryo00miss", "cats": ["marshall", "national"], "key": true, "status": "CORRECTED"}, {"src": [110], "date": "1886-03-19", "display_date": "March 19, 1886", "title": "E. H. Loughery leaves for Abilene", "text": "E. H. Loughery left Marshall to join the Abilene Daily Reporter. The Marshall Messenger called him \"one of the best writers of his age we have ever met\" and a man of \"strict integrity.\"", "source": "Marshall Messenger, March 19, 1886, p. 2", "url": "", "cats": ["marshall"], "key": false, "status": "RECORD-ONLY"}, {"src": [111], "date": "1886-03-19", "display_date": "March 19, 1886", "title": "Sexton practicing law in Colorado", "text": "The Marshall Messenger reported that F. B. Sexton, \"late of Marshall,\" had formed the law firm of Sexton and Smith in Colorado.", "source": "Marshall Messenger, March 19, 1886, p. 3", "url": "", "cats": ["marshall"], "key": false, "status": "RECORD-ONLY"}, {"src": [151], "date": "1886-04-07", "display_date": "April 7, 1886", "title": "Edmund Key marries Connie Garrett", "text": "Edmund Key, son of Mary Key, the original holder of Certificate 1656, married Miss Connie Garrett at Wills Point. She was a niece of Capt. Garrett, president of the First National Bank of Marshall. The Marshall Messenger described Key, then the bank's cashier, as a man whose business record \"has all been made in Marshall; and is a record of honor and probity.\"", "source": "Marshall Messenger, April 9, 1886, p. 3", "url": "", "cats": ["certificate", "marshall"], "key": false, "status": "CORRECTED"}, {"src": [105], "date": "1886-04-14", "display_date": "April 14, 1886", "title": "Gould answers Powderly", "text": "Replying to a letter from Knights of Labor leader Terence V. Powderly, Jay Gould wrote: \"The contest is, not between your order and me, but between your order and the laws of the land.\"", "source": "Jay Gould to T. V. Powderly, New York, April 14, 1886, in Missouri Bureau of Labor Statistics, Official History of the Great Strike of 1886, pp. 96 to 100", "url": "https://archive.org/details/officialhistoryo00miss", "cats": ["national"], "key": false, "status": "CORRECTED"}, {"src": [113], "date": "1886-04-16", "display_date": "April 16, 1886", "title": "The Messenger answers its critics", "text": "Answering readers who said it had printed \"strike literature,\" the Marshall Messenger wrote: \"The subject is hard, the blows are often hard, and the result is always hard; hard to the railroad, hard to the public, and hard to the strikers.\" It closed, \"We look for improvement.\"", "source": "Marshall Messenger, April 16, 1886, p. 2", "url": "", "cats": ["marshall"], "key": false, "status": "RECORD-ONLY"}, {"src": [114], "date": "1886-04-30", "display_date": "April 30, 1886", "title": "Testimony on the Hall discharge", "text": "The Marshall Messenger reported testimony before the congressional committee investigating the strike that the controversy over Hall's discharge \"was not the cause of the strike, and was but a subterfuge; the real cause was the refusal of the receivers to comply with an irrevocable demand.\" It also reported testimony that Hall \"was unpopular with the strikers themselves.\"", "source": "Marshall Messenger, April 30, 1886, p. 4", "url": "", "cats": ["marshall", "courts"], "key": false, "status": "RECORD-ONLY"}, {"src": "app-115", "date": "1886-05-04", "display_date": "May 4, 1886", "title": "The Great Southwest Strike is called off", "text": "Two months after the Marshall shopmen walked out, the Great Southwest Strike was officially declared \"off\" on May 4, 1886. By May, freight traffic had resumed on the Gould lines.", "source": "Missouri Bureau of Labor Statistics, The Official History of the Great Strike of 1886 on the Southwestern Railway System (1886), p. 114; Theresa A. Case, \"Great Southwestern Strike,\" Encyclopedia of Arkansas", "url": "https://archive.org/details/officialhistoryo00miss", "cats": ["marshall", "railroad", "national"], "key": false, "status": "VERIFIED"}, {"src": [116], "date": "1886-07-06", "display_date": "July 6, 1886", "title": "Congress forfeits the Atlantic and Pacific grant", "text": "Congress declared forfeited the unearned lands granted to the Atlantic and Pacific Railroad Company and restored them to the public domain. The U.S. Supreme Court upheld the forfeiture in 1897.", "source": "Act of July 6, 1886, ch. 637, 24 Stat. 123; Atlantic & Pacific R.R. Co. v. Mingus, 165 U.S. 413 (1897); United States v. Southern Pacific R.R. Co., 146 U.S. 570 (1892)", "url": "https://www.govinfo.gov/content/pkg/USREPORTS-165/pdf/USREPORTS-165-413.pdf", "cats": ["national", "land"], "key": false, "status": "CORRECTED"}, {"src": [117], "date": "1886-07-09", "display_date": "July 9, 1886", "title": "L. L. Keller succeeds A. A. Egbert", "text": "The Marshall Messenger reported that L. L. Keller had taken the place of A. A. Egbert as general superintendent of the Texas and Pacific. The office force presented Egbert with a gold-headed cane \"as a token of their high regard for him as an officer.\"", "source": "Marshall Messenger, July 9, 1886, p. 3 (\"R.R. Notes\")", "url": "", "cats": ["railroad", "marshall"], "key": false, "status": "RECORD-ONLY"}, {"src": [118], "date": "1886-07-30", "display_date": "July 30, 1886", "title": "C. A. Hall takes a job in Monroe", "text": "C. A. Hall, foreman of the freight car department at the Texas and Pacific shops in Marshall, whose discharge set off the Great Southwest Strike, took a position in the shops at Monroe, Louisiana, on the Vicksburg, Shreveport and Pacific road.", "source": "Marshall Messenger, July 30, 1886, p. 3; Handbook of Texas Online, \"Great Southwest Strike\" (firing of a foreman in Marshall started the strike)", "url": "https://www.tshaonline.org/handbook/entries/great-southwest-strike", "cats": ["marshall", "railroad"], "key": false, "status": "RECORD-ONLY"}, {"src": [120], "date": "1886-09-10", "display_date": "September 10, 1886", "title": "Marshall Gas and Water Supply Company organized", "text": "The Marshall Gas and Water Supply Company organized with $25,000 in capital stock. Directors were E. J. Fry, E. Key, W. H. Pope, T. G. Macy and M. L. Weisman, with Fry as president and Edmund Key as vice president.", "source": "Marshall Messenger, September 10, 1886, p. 3", "url": "", "cats": ["marshall", "certificate"], "key": false, "status": "RECORD-ONLY"}, {"src": [122], "date": "1886-09-30", "display_date": "September 30, 1886", "title": "Thorne signs T&P report to the Comptroller", "text": "The Texas and Pacific's annual report to the Texas Comptroller, dated September 30, 1886, was signed by L. S. Thorne as acting general superintendent and Jno. L. Weller as treasurer. It listed 183,946 acres of land sold and 3,038,960 acres unsold. The Comptroller stamped it received on October 25, 1886.", "source": "Texas and Pacific Railway annual report to the Texas Comptroller, September 30, 1886, Texas State Library and Archives (photographed by J. S. Thorne)", "url": "", "cats": ["railroad", "land"], "key": false, "status": "RECORD-ONLY"}, {"src": [123, 124], "date": "1886-10-15", "display_date": "October 1886", "title": "Tri-Weekly Herald sold to J. J. Jennings", "text": "Howard Hamments sold the Marshall Tri-Weekly Herald to J. J. Jennings. T. P. Hawley retired as editor and Henry Loughery became editor. Welcoming the change, the Messenger wrote that the Herald's \"form is familiar, although another hand guides the pen and type.\"", "source": "Marshall Messenger, October 15, 1886, p. 3", "url": "", "cats": ["marshall"], "key": false, "status": "CORRECTED"}, {"src": [125, 126], "date": "1886-10-29", "display_date": "October 29, 1886", "title": "Circular No. 15 reorganizes T&P management", "text": "Receivers John C. Brown and Lionel A. Sheldon issued Circular No. 15 from Dallas, abolishing the offices of general superintendent and general agents and naming George Noble general manager, effective November 1, 1886. Division superintendents and other officers were to report directly to him. The Marshall Messenger said the change \"has been favorably received by railroad men generally.\"", "source": "Marshall Messenger, November 5, 1886, p. 1 (Circular No. 15, dated October 29, 1886)", "url": "", "cats": ["railroad"], "key": false, "status": "CORRECTED"}, {"src": [127, 130], "date": "1886-11", "display_date": "November 1886", "title": "Thorne named Master of Transportation, moves to Dallas", "text": "L. S. Thorne, superintendent of the Texas and Pacific's eastern division at Marshall, was appointed master of transportation with headquarters at Dallas. W. Anderson was named to succeed him as division superintendent. Thorne left Marshall for Dallas in mid-November 1886.", "source": "Marshall Tri-Weekly Herald, November 18, 1886 (original issue in the Thorne family papers)", "url": "", "cats": ["railroad", "marshall", "certificate"], "key": false, "status": "CORRECTED"}, {"src": [128], "date": "1886-11-12", "display_date": "November 12, 1886", "title": "Messenger prints Pope's railroad office bill", "text": "The Marshall Messenger called \"Hon. Alex Pope's bill to compel railroads to maintain their general offices and headquarters in the state\" the \"all-absorbing subject\" for Marshall and Harrison County. The bill required each railroad chartered by Texas to keep its general offices, including its master of transportation, at the place named in its charter, on pain of forfeiting its charter. This is the last issue before the certified gap in the Messenger's surviving files.", "source": "Marshall Messenger, November 12, 1886, p. 5; Marshall Public Library notarized certification (2025), as stated in Thorne v. Union Pacific, Complaint, Dist. Ct. Douglas County, Neb. (2026), para. 44", "url": "", "cats": ["marshall", "courts"], "key": false, "status": "CORRECTED"}, {"src": [129, 131], "date": "1886-11-15", "display_date": "November 15, 1886", "title": "Marshall friends give Thorne a silver service", "text": "On the night before Thorne left, railroad men and Marshall friends gathered at roadmaster Mike McDonough's office and presented a silver tea service and salver bought at Copeland's, engraved \"To the mother of L. S. Thorne, from his friends in Texas.\" Because Thorne held that an officer should accept no reward for doing his duty, they gave it to his mother. Thorne replied that, offered that way, he prized it \"a thousand fold more.\"", "source": "Marshall Tri-Weekly Herald, November 18, 1886 (original issue in the Thorne family papers); silver service in the Thorne family", "url": "", "cats": ["marshall", "certificate"], "key": false, "status": "RECORD-ONLY"}, {"src": [132], "date": "1886-11-19", "display_date": "November 19, 1886", "title": "Certified newspaper gap begins", "text": "The surviving files of the Marshall Messenger lack the issues from November 19, 1886, to February 15, 1889. Two neighboring papers show the same years: the Jefferson Jimplecute from November 13, 1886, to January 28, 1889, and the Panola Watchman from November 15, 1886, to February 1, 1889. The Marshall Public Library, the publisher of the Jimplecute, and the Panola County Historical and Genealogical Association each certified this in notarized statements in November and December 2025.", "source": "Notarized certifications of the Marshall Public Library, the Jefferson Jimplecute, and the Panola County Historical and Genealogical Association (Nov. and Dec. 2025); Thorne v. Union Pacific, Complaint, Dist. Ct. Douglas County, Neb. (2026), para. 44", "url": "", "cats": ["marshall"], "key": true, "status": "CORRECTED"}, {"src": [136], "date": "1887-02-26", "display_date": "February 26, 1887", "title": "Cleveland paper reports T&P reorganization talks", "text": "The Cleveland Plain Dealer ran \"The Texas & Pacific Railroad: Money, Finance, Complications, and Probabilities of Its Future,\" reporting reorganization discussions then under way. The reorganization plan in effect was dated August 13, 1886.", "source": "The Plain Dealer (Cleveland, Ohio), February 26, 1887, p. 2; plan date per Texas and Pacific annual report for 1902, as stated in Thorne v. Union Pacific, Complaint (Neb. 2026), para. 44", "url": "", "cats": ["railroad", "national"], "key": false, "status": "RECORD-ONLY"}, {"src": [137], "date": "1887-04-18", "display_date": "April 18, 1887", "title": "R. W. Loughery leaves to serve as consul", "text": "Col. R. W. Loughery, veteran Marshall newspaperman and from 1875 editor of the Tri-Weekly Herald, left Marshall for his post as United States consul at Acapulco, Mexico, traveling by way of El Paso and San Diego. His family remained in Marshall for the time being. He returned to Marshall after President Cleveland's term ended.", "source": "Waco Daily Day-Globe, April 19, 1887, p. 5 (dateline Marshall, April 18); Handbook of Texas Online, \"Loughery, Robert W.\"", "url": "https://www.tshaonline.org/handbook/entries/loughery-robert-w", "cats": ["marshall"], "key": false, "status": "VERIFIED"}, {"src": [138], "date": "1887-05-10", "display_date": "May 10, 1887", "title": "Chicago Tribune: \"Done to Death by Gould\"", "text": "The Chicago Tribune published a long article headlined \"Done to Death by Gould,\" on the inner history of the Texas and Pacific, written from the side of its stockholders. The article put the road's lands at \"something like 4,000,000 acres.\"", "source": "Chicago Tribune, May 10, 1887, p. 10", "url": "", "cats": ["national", "railroad"], "key": false, "status": "RECORD-ONLY"}, {"src": [140, 153], "date": "1887-08-04", "display_date": "August 4, 1887", "title": "Thirty-nine land deeds to Canda, Drake and Strauss", "text": "The Texas and Pacific, the trustees of its 1875 and 1876 income and land grant mortgages (Charles E. Satterlee and George J. Gould), and receivers Brown and Sheldon signed thirty-nine deeds dated August 4, 1887, conveying railroad lands in forty Texas counties to Charles J. Canda, Simeon J. Drake and William Strauss. A separate deed, No. 1241, conveyed the company's land certificates. When the El Paso County deed for 1,302,009 acres was recorded in July 1888, the El Paso Times reported it had been held in escrow since its signing and bore Jay Gould's signature as president.", "source": "Texas Pacific Land Trust, Declaration of Trust, Feb. 1, 1888 (SEC EDGAR, Exhibit 3.1); El Paso Times, July 14, 1888, p. 1; Austin Statesman, July 15, 1888, p. 2", "url": "https://www.sec.gov/Archives/edgar/data/97517/000093244003000112/texaspacificdecl_oftrust.txt", "cats": ["land"], "key": false, "status": "CORRECTED"}, {"src": [141, 144], "date": "1887-09-10", "display_date": "September 10, 1887", "title": "Foreclosure sale notices run in Philadelphia", "text": "The Philadelphia Inquirer began running a commissioners' sale notice for the Texas and Pacific's Eastern and Rio Grande divisions and the property under the income and land grant mortgages of May 15, 1875, and March 23, 1876. The notice allowed bondholders to pay with their bonds and was signed by John C. Brown and Lionel A. Sheldon as commissioners. It ran for several weeks, including October 27, 1887.", "source": "The Philadelphia Inquirer, September 10, 1887, p. 7, and October 27, 1887, p. 7; mortgage dates confirmed in Texas & Pacific Ry. Co. v. Marlor, 123 U.S. 687 (1887)", "url": "", "cats": ["railroad", "land"], "key": false, "status": "RECORD-ONLY"}, {"src": [143], "date": "1887-09-28", "display_date": "September 28, 1887", "title": "Twenty-two transfers of land-sale contracts", "text": "Twenty-two instruments dated September 28, 1887, transferred to Canda, Drake and Strauss the unpaid contracts for the purchase of lands under the income and land grant mortgage, covering lands in twenty-two counties.", "source": "Texas Pacific Land Trust, Declaration of Trust, Feb. 1, 1888 (SEC EDGAR, Exhibit 3.1)", "url": "https://www.sec.gov/Archives/edgar/data/97517/000093244003000112/texaspacificdecl_oftrust.txt", "cats": ["land"], "key": false, "status": "CORRECTED"}, {"src": [145], "date": "1887-11-08", "display_date": "November 8, 1887", "title": "Texas lines of the T&P sold at Marshall", "text": "At a foreclosure sale at Marshall, Gen. Isaac J. Wistar, for the bondholders' committee, bought the Eastern and Transcontinental divisions for $6,000,000 and the Rio Grande division for $4,000,000. The Fort Worth Daily Gazette expected Governor Brown to be made president of the new company. Union Pacific's expert in a 2015 lawsuit over Certificate 1656 later wrote that the committee never confirmed the sales with the receivership court.", "source": "Fort Worth Daily Gazette, November 9, 1887, p. 4; The Philadelphia Inquirer, November 4, 1887, p. 7 (sale set for 'Tuesday next' at Marshall), quoted in Expert Report of Prof. Stephen J. Lubben, Thorne v. Union Pacific Corp., No. 1:15-cv-561-RP (W.D. Tex.), Dkt. 76-3, at 37 to 38; Quad-City Times, November 10, 1887, p. 2", "url": "https://www.loc.gov/resource/sn86064205/1887-11-09/ed-1/?sp=4", "cats": ["railroad", "marshall"], "key": true, "status": "CORRECTED"}, {"src": [146], "date": "1887-12-19", "display_date": "December 19, 1887", "title": "Supreme Court rules for a T&P bondholder", "text": "In Texas & Pacific Railway Co. v. Marlor, the U.S. Supreme Court, in an opinion by Justice Blatchford, affirmed a judgment of $23,204.99 for Henry S. Marlor, holder of 150 income and land grant bonds. The company had paid the 1882 and 1883 interest neither in money nor by exercising its option to pay in scrip.", "source": "Texas & Pacific Ry. Co. v. Marlor, 123 U.S. 687 (1887)", "url": "https://www.govinfo.gov/content/pkg/USREPORTS-123/pdf/USREPORTS-123-687.pdf", "cats": ["courts", "land"], "key": false, "status": "VERIFIED"}, {"src": [147], "date": "1888-01-11", "display_date": "January 11, 1888", "title": "Grant and Thorne meet Receiver Brown", "text": "The El Paso Times reported that general manager John A. Grant and L. S. Thorne, superintendent of transportation, had returned from New Orleans, where they went to meet Receiver Brown. Grant said he knew nothing of when the reorganization would take place: \"It might take place in a month or a year.\"", "source": "El Paso Times, January 11, 1888, p. 5", "url": "", "cats": ["railroad"], "key": false, "status": "RECORD-ONLY"}, {"src": [149], "date": "1888-02-01", "display_date": "February 1, 1888", "title": "Texas Pacific Land Trust created", "text": "Charles J. Canda, Simeon J. Drake and William Strauss signed the Declaration of Trust, holding the conveyed lands for the holders of certificates of proprietary interest, up to $10,370,000, under an April 6, 1887 agreement between the bond and stockholders' committee and a committee of the income and land grant bondholders, of which Drake was a member. The trustees received \"all the powers in respect of said property of an absolute owner.\" Texas Pacific Land describes the trust as holding 3.5 million acres of Texas land.", "source": "Texas Pacific Land Trust, Declaration of Trust, Feb. 1, 1888, acknowledged May 28 to 31, 1888 (SEC EDGAR, Exhibit 3.1); Texas Pacific Land, \"About\" (texaspacific.com)", "url": "https://www.sec.gov/Archives/edgar/data/97517/000093244003000112/texaspacificdecl_oftrust.txt", "cats": ["land"], "key": true, "status": "VERIFIED"}, {"src": [150], "date": "1888-03-26", "display_date": "March 26, 1888", "title": "T&P stockholders form a protective committee", "text": "Dissatisfied Texas and Pacific stockholders met in New York and named a committee to \"protect the stockholders of said company from the schemes now on foot to take the control of the railway out of the hands of the present owners without adequate compensation,\" with Russell Sage as chairman. Holders in Amsterdam were said to own the largest single block of the stock.", "source": "Chicago Tribune, March 27, 1888, p. 2 (\"Dissatisfied Stockholders\")", "url": "", "cats": ["railroad", "national"], "key": false, "status": "RECORD-ONLY"}, {"src": [152], "date": "1888-05-04", "display_date": "May 4, 1888", "title": "Brown expected as T&P president", "text": "The Fort Worth Gazette reported \"from good authority\" that Governor John C. Brown had been agreed upon as president of the Texas and Pacific, with George Gould as first vice president. Brown was still the court's receiver at the time.", "source": "Fort Worth Daily Gazette, May 4, 1888, p. 8", "url": "https://www.loc.gov/resource/sn86064205/1888-05-04/ed-1/?sp=8", "cats": ["railroad"], "key": false, "status": "RECORD-ONLY"}, {"src": [155, 156], "date": "1888-10-31", "display_date": "October 31, 1888", "title": "T&P receivership ends; Brown becomes president", "text": "The receivership that began December 16, 1885, ended when the court discharged John C. Brown as receiver on October 31, 1888, under an order of October 26, and he returned the property to the company. Two days later the Fort Worth Daily Gazette called him \"President Brown,\" and his circular kept all of the receiver's employees in the company's service.", "source": "Texas & Pacific Ry. Co. v. Johnson, 151 U.S. 81 (1894); Fort Worth Daily Gazette, November 3, 1888, p. 4", "url": "https://www.govinfo.gov/content/pkg/USREPORTS-151/pdf/USREPORTS-151-81.pdf", "cats": ["railroad", "courts"], "key": false, "status": "VERIFIED"}, {"src": [157, 158], "date": "1889-01-01", "display_date": "January 1, 1889", "title": "El Paso Real Estate Company incorporated", "text": "John C. Brown, general manager George Noble, El Paso land agent Charles R. Morehead, H. S. Morman and James A. Bassett incorporated the El Paso Real Estate Company.", "source": "El Paso Times, January 1, 1889, p. 7", "url": "", "cats": ["land", "railroad"], "key": false, "status": "RECORD-ONLY"}, {"src": [158], "date": "1889-01-28", "display_date": "January 28, 1889", "title": "Brown argues against a railroad commission", "text": "Speaking for the Texas and Pacific before the Texas House Committee on Internal Improvements, John C. Brown opposed creating a state railroad commission, calling it \"Unnecessary, Expensive and Unjust.\" The Fort Worth Daily Gazette printed his speech.", "source": "Fort Worth Daily Gazette, January 29, 1889, pp. 1 and 6", "url": "https://www.loc.gov/resource/sn86064205/1889-01-29/ed-1/?sp=1", "cats": ["courts", "railroad"], "key": false, "status": "VERIFIED"}, {"src": [159], "date": "1889-02-15", "display_date": "February 15, 1889", "title": "Certified newspaper gap ends", "text": "The certified gap in the surviving Marshall Messenger files runs through February 15, 1889. The Jefferson Jimplecute's ends January 28, 1889, and the Panola Watchman's February 1, 1889.", "source": "Notarized certifications (Nov. and Dec. 2025), as stated in Thorne v. Union Pacific, Complaint, Dist. Ct. Douglas County, Neb. (2026), para. 44", "url": "", "cats": ["marshall"], "key": false, "status": "CORRECTED"}, {"src": [161], "date": "1889-07-31", "display_date": "July 31, 1889", "title": "Marshall welcomes T&P officers back", "text": "A reception at the Bachelors' League honored returning Texas and Pacific officers, including general manager John A. Grant and L. S. Thorne. Col. F. B. Sexton welcomed them and said a \"better understanding existed between the Texas & Pacific road and the city of Marshall.\" Some forty or fifty gentlemen attended the reception for officials the paper said were spending the night in the city, \"their future home.\"", "source": "Marshall Messenger, August 2, 1889, p. 3 (\"General Officers Entertained\")", "url": "", "cats": ["marshall", "railroad"], "key": false, "status": "RECORD-ONLY"}, {"src": [162], "date": "1889-08-17", "display_date": "August 17, 1889", "title": "John C. Brown dies", "text": "Governor John C. Brown, president of the Texas and Pacific, died at Red Boiling Springs, Tennessee, of a hemorrhage of the stomach. His obituary noted he became general solicitor of the Gould system in 1876, was appointed a receiver of the Texas and Pacific in 1885, and became president of the reorganized company when the receivership ended in 1888.", "source": "Fort Worth Daily Gazette, August 18, 1889, p. 9", "url": "https://www.loc.gov/resource/sn86064205/1889-08-18/ed-1/?sp=9", "cats": ["railroad"], "key": false, "status": "VERIFIED"}, {"src": [163, 164], "date": "1889-11-14", "display_date": "November 1889", "title": "Marshall presses suits over T&P offices", "text": "At a Marshall city council meeting, with F. B. Sexton as secretary, W. M. Johnston reported on the suits brought by Marshall and Harrison County to compel the return of the Texas and Pacific's offices to Marshall. The Messenger wrote that the company's appeal would \"go far towards lessening the bitterness of the people of Marshall towards the Railway company.\"", "source": "Marshall newspaper, November 14, 1889; Marshall Messenger, November 22, 1889", "url": "", "cats": ["marshall", "courts"], "key": false, "status": "RECORD-ONLY"}, {"src": [119], "date": "1890", "display_date": "1890", "title": "Thorne's rules with the conductors' committee", "text": "In 1890 correspondence with the Texas and Pacific's Committee of Conductors, L. S. Thorne set terms that included eight hours of rest after sixteen hours of service, an investigation within five days before any dismissal, and the right to representation.", "source": "L. S. Thorne correspondence with the Committee of Conductors, 1890 (Thorne family papers)", "url": "", "cats": ["railroad"], "key": false, "status": "CORRECTED"}, {"src": [165], "date": "1890-05-19", "display_date": "May 19, 1890", "title": "Supreme Court decides Marshall's case against T&P", "text": "In Texas & Pacific Railway Co. v. City of Marshall, the U.S. Supreme Court held that the railroad's 1872 promise to \"permanently establish\" its eastern terminus, Texas office and shops at Marshall, in return for $300,000 and sixty-six acres, was performed by keeping them there about eight years. It reversed the lower court's decree for the city and ordered the bill dismissed. Justice Brewer dissented.", "source": "Texas & Pacific Ry. Co. v. City of Marshall, 136 U.S. 393 (1890)", "url": "https://www.govinfo.gov/content/pkg/USREPORTS-136/pdf/USREPORTS-136-393.pdf", "cats": ["courts", "marshall"], "key": true, "status": "VERIFIED"}, {"src": [166], "date": "1890-06-23", "display_date": "June 23, 1890", "title": "L. S. Thorne elected a T&P director", "text": "L. S. Thorne was elected to the board of directors of the Texas and Pacific Railway.", "source": "Lansing S. Thorne obituary, Marshall Messenger, February 28, 1917", "url": "", "cats": ["railroad", "certificate"], "key": false, "status": "RECORD-ONLY"}, {"src": [167], "date": "1890-07-25", "display_date": "July 25, 1890", "title": "James Harper Starr dies in Marshall", "text": "James Harper Starr, Republic of Texas treasurer, land agent and banker, and a director in 1853 of the Texas Western Railroad Company (later the Southern Pacific), died in Marshall and was buried in Greenwood Cemetery. His papers are held at the Briscoe Center for American History in Austin.", "source": "Handbook of Texas Online, \"Starr, James Harper\"; Thorne v. Union Pacific, Complaint (Neb. 2026), para. 54 (Starr papers, Briscoe Center)", "url": "https://www.tshaonline.org/handbook/entries/starr-james-harper", "cats": ["marshall"], "key": false, "status": "CORRECTED"}, {"src": [169], "date": "1891", "display_date": "1891", "title": "State sues T&P over land grant acreage", "text": "Attorney General Charles A. Culberson sued to recover 301,893 acres from the Texas and Pacific, on the ground that land had been granted partly for sidetracks and partly on land not subject to location. The state recovered 256,046 acres.", "source": "Handbook of Texas Online, \"Texas and Pacific Railway\"", "url": "https://www.tshaonline.org/handbook/entries/texas-and-pacific-railway", "cats": ["land", "courts"], "key": false, "status": "CORRECTED"}, {"src": [168], "date": "1891-04-03", "display_date": "April 3, 1891", "title": "Texas creates the Railroad Commission", "text": "The Texas Legislature created the Railroad Commission of Texas, with authority over railroad rates and operations. Governor James S. Hogg named John H. Reagan its first chairman. The commission's annual report form asked each railroad whether it had been sold at a judicial or other sale.", "source": "Railroad Commission of Texas, \"RRC History\"; Handbook of Texas Online, \"Railroad Commission\"; Texas Railroad Commission annual report form, Question 14", "url": "https://www.rrc.texas.gov/about-us/rrc-history/", "cats": ["courts", "railroad"], "key": false, "status": "VERIFIED"}, {"src": [170], "date": "1891-11-30", "display_date": "November 30, 1891", "title": "T&P tells the Railroad Commission: no sale", "text": "Asked in Question 14 whether there had been any judicial or other sale of the railroad, the Texas and Pacific answered in its report to the Railroad Commission: \"There has been no sale. The finances of this Company were reorganized under the modified agreement, a copy of which is hereto attached, in the year 1888. There was no sale or foreclosure as was contemplated in the modified agreement.\" The report was signed by Jno. A. Grant, third vice president, and R. Fenby, auditor, and sworn in Dallas County.", "source": "Texas and Pacific Railway Co., Annual Report to the Railroad Commission of Texas for the year ended June 30, 1891, p. 9, Texas State Library and Archives", "url": "", "cats": ["railroad", "courts"], "key": true, "status": "VERIFIED"}, {"src": [171], "date": "1892-05-10", "display_date": "May 10, 1892", "title": "Thorne made General Superintendent", "text": "After John A. Grant resigned as general manager, Jay Gould, as president, announced L. S. Thorne as general superintendent: \"All departments of this company are subject to his orders.\" That morning the road's special agent and the general roadmaster, Mr. Summers, were let go and both offices abolished. The next day Page Harris wrote to Thorne from Linwood, Kansas, that he was glad Thorne was at last where he should have been all along.", "source": "El Paso dispatch of May 10, 1892, newspaper clipping; Page Harris to L. S. Thorne, May 11, 1892 (Thorne family papers)", "url": "", "cats": ["railroad"], "key": false, "status": "CORRECTED"}, {"src": [135], "date": "1892-10-04", "display_date": "October 4, 1892", "title": "E. Key buys the Marshall to Harleton line", "text": "E. Key of Marshall bought the Paris, Marshall and Sabine Pass Railway, a completed line between Marshall and Harleton, at a receiver's sale. In 1897 the Texas Southern Railway was chartered to acquire it from Key and his associates, and its successor, the Marshall and East Texas, with Key on its first board, later sold two miles of track and its Marshall terminal to the Texas and Pacific.", "source": "Handbook of Texas Online, \"Texas Southern Railway,\" \"Marshall and East Texas Railway,\" and \"Harleton, TX\"", "url": "https://www.tshaonline.org/handbook/entries/texas-southern-railway", "cats": ["railroad", "marshall", "certificate"], "key": false, "status": "CORRECTED"}, {"src": [172], "date": "1892-12-02", "display_date": "December 2, 1892", "title": "Jay Gould dies", "text": "Jay Gould died in New York. Control of his railroads, including the Missouri Pacific and its interest in the Texas and Pacific, passed to his son George J. Gould.", "source": "New York Times, December 3, 1892; Maury Klein, The Life and Legend of Jay Gould (1986)", "url": "https://en.wikipedia.org/wiki/Jay_Gould", "cats": ["railroad", "national"], "key": false, "status": "VERIFIED"}, {"src": [173], "date": "1893-07-11", "display_date": "July 11, 1893", "title": "Thorne named Third Vice President and General Manager", "text": "L. S. Thorne was promoted to third vice president and general manager of the Texas and Pacific.", "source": "Lansing S. Thorne obituary, Marshall Messenger, February 28, 1917", "url": "", "cats": ["railroad", "certificate"], "key": false, "status": "RECORD-ONLY"}, {"src": [174], "date": "1894-03-30", "display_date": "March 1894", "title": "Railroads refuse Fry's industrial army at El Paso", "text": "The Marshall Messenger reported that officials of the Texas and Pacific and the Southern Pacific were \"determined Frey's regiment shall not ride on their trains\" as the industrial army camped at their El Paso junction. The Southern Pacific stopped eastbound freights, and the Texas and Pacific would carry no empty freight cars out of El Paso.", "source": "Marshall Messenger, March 30, 1894, p. 3", "url": "", "cats": ["railroad", "national"], "key": false, "status": "CORRECTED"}, {"src": [175], "date": "1894-09-13", "display_date": "September 13, 1894", "title": "Thorne joins the El Paso Northern board", "text": "The El Paso Northern Railway Company is chartered to take over the former Kansas City, El Paso and Mexican Railroad Company of Texas, which Jay Gould had bought at foreclosure on April 28, 1892. Its first board includes George J. Gould, Edwin Gould, Charles E. Satterlee, Charles R. Morehead of El Paso, and William H. Abrams, L. S. Thorne and E. L. Sargent of Dallas.", "source": "Handbook of Texas Online, \"El Paso Northern Railway\" (text as copied in JS's research email of Nov. 3, 2017, Drive file Email.pdf)", "url": "", "cats": ["railroad"], "key": false, "status": "CORRECTED"}, {"src": [176, 177], "date": "1895-04-27", "display_date": "April 27, 1895", "title": "L. S. Thorne marries Mary Cunning", "text": "L. S. Thorne marries Mary Cunning in Millersburg, Ohio, and brings her home to Dallas. His handwritten will, dated May 8, 1895, leaves his estate to her and names her executrix.", "source": "Encyclopedia of Texas, Vol. III; Dallas Morning News obituary, Feb. 28, 1917 (marriage in 1895); Dallas County Probate Cause PR-5107-1, will of L. S. Thorne dated May 8, 1895", "url": "", "cats": ["certificate"], "key": false, "status": "RECORD-ONLY"}, {"src": [179], "date": "1898", "display_date": "1898", "title": "Ferry named the L. S. Thorne", "text": "The Texas and Pacific puts two train ferries on the Mississippi River at New Orleans. One is named the Gouldsboro and the other the L. S. Thorne, in his honor.", "source": "T&P Topics (employee magazine), February 1955; Thorne family chain-of-title memorandum (Drive); photograph, T&P train ferry L.S. Thorne at New Orleans, c. 1938, texaspacificrailway.org", "url": "https://www.texaspacificrailway.org/ferry/texas-and-pacific-railway-ferry-l-s--thorpe-c1938-image-1465.html", "cats": ["railroad"], "key": false, "status": "RECORD-ONLY"}, {"src": [181], "date": "1902-07-08", "display_date": "July 8, 1902", "title": "Pennsylvania court upholds the construction company", "text": "In a quo warranto case brought by Attorney General John P. Elkin, the Dauphin County court finds that the California and Texas Railway Construction Company organized lawfully and had kept a continuous organization, done business and paid taxes since 1872. The opinion also records that the company's treasurer reported $1,068,947.57 of \"Southern Pacific Railway stock converted\" into its capital at its June 4, 1873 annual meeting.", "source": "Commonwealth ex rel. Elkin v. California and Texas Railway Construction Co., 5 Dauphin County Reports 181 (C.P. Dauphin Cnty., Pa. July 8, 1902) (Weiss, J.); Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), paras. 22 to 23 and Ex. C", "url": "", "cats": ["construction-co", "courts"], "key": false, "status": "CORRECTED"}, {"src": [178], "date": "1902-09-15", "display_date": "1891 to 1902", "title": "T&P reports list construction company stock", "text": "The Texas and Pacific's annual reports to the Railroad Commission of Texas list stock of the California and Texas Railway Construction Company among the stocks the railroad owned, starting with $68,000 in the report for 1891. The listing continues through the report for 1902, filed September 15, 1902.", "source": "Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), para. 42; T&P annual reports to the Railroad Commission of Texas, Texas State Library and Archives", "url": "", "cats": ["construction-co", "railroad"], "key": false, "status": "CORRECTED"}, {"src": [182], "date": "1907-02-11", "display_date": "February 11, 1907", "title": "First answer in the railroad's file", "text": "Answering John J. Hubbard of Afton, Indian Territory, about twelve shares of Southern Pacific stock, the Texas and Pacific's Secretary and Treasurer recites the sheriff's sales and the 1868 sales to R. B. Hall and Associates of Louisville. He writes, \"You can draw your own conclusions therefore as to the value of the stock you hold. The records of Harrison County, Texas, I think will confirm the data given.\"", "source": "Letter of Feb. 11, 1907, Texas and Pacific Secretary and Treasurer to John J. Hubbard (UP_004271), from Union Pacific's file of answers to holders; Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), para. 31", "url": "", "cats": ["answers"], "key": true, "status": "VERIFIED"}, {"src": [183], "date": "1908-10-18", "display_date": "October 18, 1908", "title": "Mary Key dies", "text": "Mary Hill Key, to whom Certificate 1656 was issued in 1859, dies. She was the widow of Hobart Key and the mother of Marshall banker Edmund Key.", "source": "Thorne family chain-of-title memorandum to counsel (Drive), giving Mary Hill Key's dates as June 16, 1833 to Oct. 18, 1908", "url": "", "cats": ["certificate", "marshall"], "key": false, "status": "RECORD-ONLY"}, {"src": [184], "date": "1909-12-16", "display_date": "December 16, 1909", "title": "Edmund Key sues over two Harrison County surveys", "text": "Edmund Key, P. G. Whaley and W. T. Martin file suit in Harrison County District Court claiming two tracts as joint owners: Southern Pacific Railroad Company Survey No. 437 and E. Key Survey No. 114 of 515.15 acres. The defendants include several Harrison and Upshur County residents and the Marshall and East Texas Railroad Company.", "source": "E. Key et al. v. Tom Jones et al., District Court of Harrison County, Texas, original petition filed Dec. 16, 1909, amended Sept. 27, 1912 (abstract photographed by JS, Drive IMG_1154)", "url": "", "cats": ["land", "marshall"], "key": false, "status": "VERIFIED"}, {"src": [187], "date": "1911-05-10", "display_date": "May 10, 1911", "title": "L. S. Thorne retires", "text": "L. S. Thorne resigns as vice president and general manager of the Texas and Pacific, a post he had held since July 11, 1893, and retires for his health. Employees along the line from El Paso to New Orleans send him a solid gold loving cup engraved \"L. S. Thorne, 1874-1911.\"", "source": "Dallas Morning News obituary of L. S. Thorne, Feb. 28, 1917 (resignation May 10, 1911); \"Loving Cup for L. S. Thorne,\" newspaper clipping, Dec. 1911 (Drive, 1911 retirement1.pdf)", "url": "", "cats": ["railroad"], "key": false, "status": "VERIFIED"}, {"src": [189], "date": "1912-10-01", "display_date": "October 1, 1912", "title": "Key and partners sell to Killingsworth", "text": "Edmund Key, W. L. Martin and P. G. Whaley deed their Southern Pacific survey land in Harrison County to W. H. Killingsworth. The deed is filed October 7, 1912, in Book 78, page 524.", "source": "Harrison County deed records, Book 78, p. 524 (deed dated Oct. 1, 1912, filed Oct. 7, 1912) (abstract photographed by JS, Drive IMG_1132)", "url": "", "cats": ["land", "marshall"], "key": false, "status": "VERIFIED"}, {"src": [], "date": "1913-05", "display_date": "May 1913", "title": "Same words to a 300-share holder", "text": "An inquirer writing for a client who held 300 shares receives the same recital of the Hall sales and the $150,000 decree. He is told in the same words as in 1907, \"The records of Harrison County, Texas, I think will confirm the data given.\"", "source": "Letter of May 1913 (UP_004270), Union Pacific's file of answers to holders; Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), para. 31 and Ex. D", "url": "", "cats": ["answers"], "key": false, "status": "VERIFIED"}, {"src": [190], "date": "1917-02-28", "display_date": "February 28, 1917", "title": "L. S. Thorne dies in Dallas", "text": "L. S. Thorne dies at his home at 4703 Ross Avenue in Dallas. His estate inventory, sworn in August 1917, lists bank and company stocks including 20 shares of Texas and Pacific stock. The family holds that he had already given Certificate 1656 to his wife, Mary Cunning Thorne.", "source": "Dallas County Probate Cause PR-5107-1, Estate of L. S. Thorne (application, order probating will of Aug. 7, 1917, and inventory); Dallas Morning News obituary, Feb. 28, 1917; family testimony of L. S. Thorne II (2010)", "url": "", "cats": ["certificate"], "key": false, "status": "CORRECTED"}, {"src": [], "date": "1919-04", "display_date": "April 1919", "title": "A Kentucky attorney asks where the stock went", "text": "A Kentucky attorney asks the Texas and Pacific what provision was ever made for \"taking up the said issue of Stock of the Southern Pacific Railroad Company and replacing it with other issues of stock.\" The Secretary answers, \"The bankruptcy proceedings wiped out any equity that the stock ever had and same is of no value at this time.\"", "source": "Inquiry and answer of April 1919 (UP_004238, UP_004237), Union Pacific's file of answers to holders; Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), para. 33 and Ex. D", "url": "", "cats": ["answers"], "key": false, "status": "VERIFIED"}, {"src": [192], "date": "1921-12-31", "display_date": "December 31, 1921", "title": "T&P books still carry Thorne's shares", "text": "Four years after his death, the Texas and Pacific's books still record twenty uncertificated shares in the name of L. S. Thorne. This is the last date the shares appear there.", "source": "Annual Report of the Texas and Pacific Railway Company (1921); Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), para. 64", "url": "", "cats": ["certificate", "railroad"], "key": false, "status": "VERIFIED"}, {"src": [193, 180], "date": "1923-07-21", "display_date": "July 21, 1923", "title": "Grandson Lansing Stephen Laird is born", "text": "Lansing Stephen Laird is born to Julia Thorne, daughter of L. S. and Mary Cunning Thorne, and Edgar F. Laird. He later takes the name Lansing Stephen Thorne and is known in the family as L. S. Thorne II.", "source": "Thorne family records; family chain-of-title memorandum (Drive)", "url": "", "cats": ["certificate"], "key": false, "status": "RECORD-ONLY"}, {"src": [195, 185, 186], "date": "1929-07-27", "display_date": "July 27, 1929", "title": "A counsel-approved form letter", "text": "An internal Texas and Pacific memorandum says an attached reply is \"in form approved by Counsel several years ago\" and recommends \"that the same form be used with respect to all enquiries regarding this particular stock.\" The form, sent in September 1929 and again in 1930, says the Southern Pacific had \"no stock or bonds outstanding with the exception of a bond to the State of Texas\" when it consolidated with the Texas and Pacific in 1872. A statement in the same company records lists $1,250,000 of Southern Pacific stock outstanding on March 21, 1872.", "source": "T&P memorandum of July 27, 1929 (UP_004182); form letter of Sept. 27, 1929 (UP_004183); 1930 letters (UP_004178, UP_004177, UP_004168, UP_004167); statement of stock outstanding March 21, 1872 (UP_003884); Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), paras. 26, 31, 34", "url": "", "cats": ["answers"], "key": true, "status": "CORRECTED"}, {"src": [196, 198], "date": "1931-05", "display_date": "May 1931", "title": "Construction company stock charged off", "text": "The Texas and Pacific's report to the Interstate Commerce Commission for 1931 records its holding of California and Texas Railway Construction Company stock as disposed of in May 1931, with the remark \"Charged off - Expiration. None then dissolved.\"", "source": "T&P Annual Report to the Interstate Commerce Commission for 1931, Texas State Library and Archives; Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), para. 42", "url": "", "cats": ["construction-co", "railroad"], "key": false, "status": "CORRECTED"}, {"src": [197, 206], "date": "1933", "display_date": "1933", "title": "The certificate is shown to a ten-year-old", "text": "Mary Cunning Thorne takes her grandson, ten-year-old L. S. Thorne II, to the First National Bank of Dallas, shows him Certificate 1656, and tells him it was his grandfather's and will be his. As he later recalled it, she told him it was valuable, that it would have to be taken to court to be redeemed, and that the charters were enacted to protect it. The federal courts later found the family knew by 1933 that court action would likely be needed.", "source": "Written testimony of L. S. Thorne II, Sept. 29, 2010 and Feb. 20, 2011 (family records); Thorne v. Union Pacific Corp., No. 18-50019 (5th Cir. Nov. 20, 2018)", "url": "https://www.ca5.uscourts.gov/Opinions/unpub/18/18-50019.0.pdf", "cats": ["certificate"], "key": false, "status": "CORRECTED"}, {"src": [199], "date": "1945-04-21", "display_date": "April 21, 1945", "title": "Mary Cunning Thorne dies", "text": "Mary Cunning Thorne, widow of L. S. Thorne, dies. Her will lists the stocks in her estate; the family holds that Certificate 1656 had already passed to her grandson.", "source": "Death record of Mary C. Thorne (as certified for Vol. III); probate of Mary C. Thorne (family records); Thorne v. Union Pacific Corp., No. 1:15-CV-561-RP, Dkt. 118 (W.D. Tex. Nov. 21, 2017) (her death a stipulated fact)", "url": "", "cats": ["certificate"], "key": false, "status": "RECORD-ONLY"}, {"src": [230], "date": "1949-10-16", "display_date": "1949 to 2002", "title": "SPRR survey names still in use", "text": "Marshall News-Messenger reports show land still identified by Southern Pacific Railroad survey names: a 1949 timber deed naming \"SPRR, E. Key,\" a 1983 Panola County well named \"No. 7 Frost Lumber Co. (SPRR),\" and 2002 drilling on \"SPRR Survey A-698\" in Harrison County.", "source": "Marshall News-Messenger, Oct. 16, 1949; July 3, 1983, p. 7; July 14, 2002, p. 23", "url": "", "cats": ["land", "marshall"], "key": false, "status": "RECORD-ONLY"}, {"src": [], "date": "1951", "display_date": "1951", "title": "Grandson looks into the certificate's value", "text": "L. S. Thorne II investigates what Certificate 1656 might be worth. The federal court later cited this inquiry in its laches ruling.", "source": "Thorne v. Union Pacific Corp., No. 1:15-CV-561-RP, Dkt. 118 (W.D. Tex. Nov. 21, 2017)", "url": "https://law.justia.com/cases/federal/district-courts/texas/txwdce/1:2015cv00561/759698/118", "cats": ["certificate"], "key": false, "status": "VERIFIED"}, {"src": [], "date": "1964-02", "display_date": "February 1964", "title": "Virginia's unclaimed property office asks", "text": "The administrator of Virginia's Unclaimed Property Act, holding a Southern Pacific certificate, writes to the Texas and Pacific's Vice President and General Counsel. He receives the same recital of sales.", "source": "Letters of Feb. 1964 (UP_003950, UP_003949), Union Pacific's file of answers to holders; Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), para. 32", "url": "", "cats": ["answers"], "key": false, "status": "VERIFIED"}, {"src": [], "date": "1969-01", "display_date": "January 1969", "title": "An attorney notes two different answers", "text": "An attorney asks for \"the names and home office addresses of all companies involved in the dissolution or reorganization\" of the Southern Pacific. He writes that the Texas and Pacific told one inquirer \"that the stockholders of the subordinate company would have received stock in the acquiring company,\" while its letter to another implied all equity was lost.", "source": "Letters of Jan. 1969 (UP_003929, UP_003930), Union Pacific's file of answers to holders; Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), para. 33", "url": "", "cats": ["answers"], "key": false, "status": "VERIFIED"}, {"src": [202], "date": "1976-10-15", "display_date": "October 15, 1976", "title": "Texas and Pacific merges into Missouri Pacific", "text": "The Texas and Pacific Railway is absorbed into the Missouri Pacific Railroad, which had controlled it since 1928.", "source": "Missouri Pacific Historical Society, \"Timeline: MP and Predecessors\" (10-15-1976 and 01-01-1928 entries); Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), para. 10", "url": "https://mopac.org/mopac-history-post/timeline-mp-and-predecessors/", "cats": ["railroad"], "key": false, "status": "CORRECTED"}, {"src": [201], "date": "1980", "display_date": "1980", "title": "Last inquiry in the railroad's file", "text": "The last inquiry about Southern Pacific stock in the railroad's file of answers dates from 1980. From 1907 on, the file records more than one hundred inquiries about more than eighty holders, families and estates.", "source": "Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), para. 31", "url": "", "cats": ["answers"], "key": false, "status": "CORRECTED"}, {"src": [204], "date": "1982-12-22", "display_date": "December 22, 1982", "title": "Union Pacific takes control of Missouri Pacific", "text": "Union Pacific gains control of the Missouri Pacific. The Missouri Pacific Railroad Company is merged into Union Pacific Railroad Company on January 1, 1997.", "source": "Missouri Pacific Historical Society, \"Timeline: MP and Predecessors\" (12-22-1982 and 01-01-1997 entries); Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), para. 10", "url": "https://mopac.org/mopac-history-post/timeline-mp-and-predecessors/", "cats": ["railroad"], "key": false, "status": "CORRECTED"}, {"src": "app-195", "date": "1985-03-05", "display_date": "March 5, 1985", "title": "Court decides who owns Land Trust Certificate 390", "text": "The Dallas Court of Appeals affirms a jury verdict awarding Texas Pacific Land Trust Certificate No. 390 to the estate of New York mining magnate J. R. DeLamar. The certificate was issued in 1888 to Blake Brothers & Company in exchange for Texas and Pacific income and land grant bonds, and was found in 1977 among old Wells Fargo papers. The case began as a State of Texas suit to escheat the certificate, filed November 11, 1961.", "source": "Martin v. United States Trust Co. of New York, 690 S.W.2d 300 (Tex. App., Dallas, March 5, 1985), No. 05-83-00623-CV", "url": "https://static.case.law/sw2d/690/html/0300-01.html", "cats": ["land", "courts"], "key": false, "status": "VERIFIED"}, {"src": [205], "date": "2005-02-13", "display_date": "February 13, 2005", "title": "Certificate passes to the great-great-grandson", "text": "L. S. Thorne II gives Certificate 1656 to his grandson, John Stephen Crumby, the great-great-grandson of L. S. Thorne. The federal court later described the certificate as received by gift in 2005.", "source": "Family conveyance records (gift papers of March 10, 2015; affidavit of July 9, 2013); Thorne v. Union Pacific Corp., No. 1:15-CV-561-RP, Dkt. 118 (W.D. Tex. Nov. 21, 2017)", "url": "https://law.justia.com/cases/federal/district-courts/texas/txwdce/1:2015cv00561/759698/118", "cats": ["certificate"], "key": false, "status": "RECORD-ONLY"}, {"src": [207], "date": "2011-06-30", "display_date": "June 30, 2011", "title": "Formal demand to Union Pacific", "text": "Houston attorney Ronald L. Bair of BairHilty, P.C. makes a formal written demand on Union Pacific Railroad Company concerning Certificate 1656, sent by certified mail to its registered agent in Dallas and to its general counsel in Omaha. On July 8 he emails photographs of the certificate's front and back.", "source": "Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), para. 11", "url": "", "cats": ["answers", "certificate"], "key": false, "status": "VERIFIED"}, {"src": [207], "date": "2011-08-03", "display_date": "August 3, 2011", "title": "Union Pacific's written answer", "text": "After a phone call that day, Union Pacific Senior General Attorney Timothy S. Dunning emails Mr. Bair an account he says comes from \"older correspondence in our files that dates to 1907.\" It recites the sales of 1860 and 1861 and the 1868 Hall sales, ends with \"In 1872, Texas and Pacific acquired SPRC,\" and says the records were filed in Harrison County, Texas. The 2026 Nebraska complaint alleges this answer was materially misleading because it stopped before the 1873 conversion of Southern Pacific stock.", "source": "E-mail of Timothy S. Dunning to Ronald L. Bair, Aug. 3, 2011, 5:47 p.m. (UP_003860); Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), paras. 12 to 19", "url": "", "cats": ["answers"], "key": true, "status": "VERIFIED"}, {"src": [], "date": "2011-09", "display_date": "2011, after the answer", "title": "Thorne goes to Harrison County", "text": "Following the answer, Thorne travels to Harrison County, where the answer said the records were filed, to examine the records of the Hall sales. His search for the Hall sales also leads him to the Supreme Court's 1882 opinion in Stevenson v. Texas Railway Co.", "source": "Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), paras. 36 to 37", "url": "", "cats": ["certificate", "marshall"], "key": false, "status": "VERIFIED"}, {"src": [208, 203], "date": "2013-09-20", "display_date": "September 20, 2013", "title": "John Crumby becomes John Stephen Thorne", "text": "Born John Stephen Crumby in 1976, the great-great-grandson of L. S. Thorne legally changes his name to John Stephen Thorne.", "source": "Court name-change order of Sept. 20, 2013 (family records); Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), para. 4", "url": "", "cats": ["certificate"], "key": false, "status": "RECORD-ONLY"}, {"src": [], "date": "2014-03-06", "display_date": "March 6, 2014", "title": "Paying for an analysis built on the answer", "text": "Thorne pays an Austin attorney $1,875 toward a memorandum analyzing the Stevenson opinion and litigation and their bearing on Certificate 1656. The memorandum is delivered March 21, 2014, and this $1,875 is the sum the 2026 complaint seeks as damages.", "source": "Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), paras. 39 to 41 and Ex. E", "url": "", "cats": ["courts", "certificate"], "key": false, "status": "VERIFIED"}, {"src": [209], "date": "2015-06-29", "display_date": "June 29, 2015", "title": "Thorne I filed in federal court", "text": "Thorne sues Union Pacific in the U.S. District Court for the Western District of Texas, No. 1:15-CV-561-RP, asking for a declaratory judgment on the number, class and value of the shares Certificate 1656 represents.", "source": "Thorne v. Union Pacific Corp., No. 1:15-CV-561-RP (W.D. Tex.), Complaint, Dkt. 1 (June 29, 2015); Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), para. 58", "url": "", "cats": ["courts"], "key": false, "status": "CORRECTED"}, {"src": [210, 211], "date": "2016-12-14", "display_date": "December 2016 to June 2017", "title": "Experts for both sides", "text": "Thorne's experts include retired U.S. Bankruptcy Judge Leif M. Clark, Timothy Vaughn of Hallett & Perrin, forensic document examiner Gerald LaPorte and valuation analyst Bryce Erickson. Union Pacific's experts include historian Maury Klein and law professor Stephen J. Lubben, whose reports conclude the shares ended in 1868 or 1872.", "source": "Expert report of Timothy Vaughn (Dec. 14, 2016); amended report of Leif M. Clark (March 31, 2017); Klein report (Dkt. 76-1) and Lubben report (Dkt. 76-3), No. 1:15-CV-561-RP; Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), paras. 48, 61, 62", "url": "", "cats": ["courts"], "key": false, "status": "CORRECTED"}, {"src": [212], "date": "2017", "display_date": "2016 to 2017", "title": "Union Pacific produces its file of answers", "text": "In discovery, Union Pacific produces its file of correspondence about Southern Pacific stock certificates. It records more than one hundred inquiries about more than eighty holders, families and estates between 1907 and 1980, with the railroad's answers.", "source": "Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), paras. 31, 37", "url": "", "cats": ["answers", "courts"], "key": false, "status": "CORRECTED"}, {"src": [213], "date": "2017-11-21", "display_date": "November 21, 2017", "title": "Thorne I decided on laches", "text": "Four days after hearing the cross-motions, Judge Robert Pitman grants Union Pacific summary judgment on laches alone and says it is unnecessary to reach Union Pacific's other arguments. The same order holds the court could not conclude the claims were time-barred and finds an earlier 2005 or 2007 phone call was not a demand and refusal. Final judgment is entered December 4, 2017.", "source": "Thorne v. Union Pacific Corp., No. 1:15-CV-561-RP, Dkt. 118 (W.D. Tex. Nov. 21, 2017); hearing transcript, Dkt. 123 (Nov. 17, 2017); Final Judgment, Dkt. 119 (Dec. 4, 2017)", "url": "https://law.justia.com/cases/federal/district-courts/texas/txwdce/1:2015cv00561/759698/118", "cats": ["courts"], "key": true, "status": "VERIFIED"}, {"src": [215, 214], "date": "2018-11-20", "display_date": "November 20, 2018", "title": "Fifth Circuit affirms on laches", "text": "On Thorne's appeal, filed January 3, 2018, the Fifth Circuit affirms in No. 18-50019 on laches. It does not address the statute of limitations.", "source": "Thorne v. Union Pacific Corp., No. 18-50019 (5th Cir. Nov. 20, 2018) (per curiam, unpublished); Notice of Appeal (Jan. 3, 2018)", "url": "https://www.ca5.uscourts.gov/Opinions/unpub/18/18-50019.0.pdf", "cats": ["courts"], "key": false, "status": "CORRECTED"}, {"src": [], "date": "2019-04-15", "display_date": "April 15, 2019", "title": "Supreme Court denies review", "text": "The U.S. Supreme Court denies Thorne's petition for certiorari in No. 18-1169, ending Thorne I.", "source": "Thorne v. Union Pacific Corp., No. 18-1169 (U.S. cert. denied Apr. 15, 2019); Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), para. 60", "url": "", "cats": ["courts"], "key": false, "status": "VERIFIED"}, {"src": [216], "date": "2020-09-28", "display_date": "September 28, 2020", "title": "Thorne II filed in Houston", "text": "Thorne files a second suit in the U.S. District Court for the Southern District of Texas in Houston. It concerns only ten of twenty uncertificated Texas and Pacific shares carried in L. S. Thorne's name, not Certificate 1656. The case is assigned to U.S. District Judge Vanessa D. Gilmore.", "source": "Thorne v. Union Pacific, No. 4:20-cv-03381 (S.D. Tex.), later No. 1:21-CV-311-RP (W.D. Tex.); Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), para. 64", "url": "", "cats": ["courts"], "key": false, "status": "CORRECTED"}, {"src": "app-221", "date": "2021-01-11", "display_date": "January 11, 2021", "title": "Land Trust becomes Texas Pacific Land Corporation", "text": "The Texas Pacific Land Trust, created by the Declaration of Trust of February 1, 1888, completes its reorganization into Texas Pacific Land Corporation, a Delaware corporation. Holders of the trust's sub-share certificates receive common stock one for one, and the company trades on the New York Stock Exchange as TPL.", "source": "Texas Pacific Land Corporation, Form 8-K, Exhibit 99.1 (press release of Jan. 11, 2021), SEC EDGAR", "url": "https://www.sec.gov/Archives/edgar/data/1811074/000121390021001303/ea133016ex99-1_texaspacific.htm", "cats": ["land"], "key": false, "status": "VERIFIED"}, {"src": [218, 219], "date": "2021-02-28", "display_date": "February 28, 2021", "title": "Houston court denies first transfer motion", "text": "Judge Gilmore of the Southern District of Texas denies Union Pacific's motion to transfer the case to Judge Pitman in Austin.", "source": "Thorne v. Union Pacific, No. 4:20-cv-03381 (S.D. Tex.), Dkt. 21 (signed Feb. 28, 2021, entered March 1, 2021) (JS's filings index)", "url": "", "cats": ["courts"], "key": false, "status": "RECORD-ONLY"}, {"src": "app-220", "date": "2021-03-05", "display_date": "March 5, 2021", "title": "Houston court sets a January 2022 trial", "text": "Judge Gilmore's scheduling order in Thorne II sets the case for trial during January 2022, with discovery to close August 6, 2021 and docket call on December 17, 2021.", "source": "Scheduling Order, Thorne v. Union Pacific, No. 4:20-cv-03381 (S.D. Tex.), Dkt. 24 (signed and entered March 5, 2021) (JS's Drive, 'Civil Scheduling Order - Gilmore.pdf')", "url": "", "cats": ["courts"], "key": false, "status": "RECORD-ONLY"}, {"src": [220], "date": "2021-04-09", "display_date": "April 9, 2021", "title": "Thorne II moves to Austin", "text": "The case is received in the Western District of Texas as No. 1:21-CV-311-RP before Judge Pitman, with referrals to Magistrate Judge Mark Lane.", "source": "Thorne v. Union Pacific, No. 1:21-CV-311-RP (W.D. Tex.), docket text entry of Apr. 9, 2021 (JS's filings index)", "url": "", "cats": ["courts"], "key": false, "status": "CORRECTED"}, {"src": [222], "date": "2022-07-26", "display_date": "July 26, 2022", "title": "Magistrate judge recommends judgment for Union Pacific", "text": "Magistrate Judge Mark Lane recommends granting Union Pacific's motion for summary judgment, including its counterclaim for a declaration about Southern Pacific and Texas and Pacific stock certificates. The report rejects Union Pacific's limitations, res judicata and expert-witness arguments, and rests the recommendation on two grounds: that Thorne raised no fact issue on ownership of the shares, and laches.", "source": "Report and Recommendation, No. 1:21-CV-311-RP, Dkt. 56 (W.D. Tex. July 26, 2022); Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), para. 64", "url": "", "cats": ["courts"], "key": false, "status": "CORRECTED"}, {"src": [223], "date": "2022-08-10", "display_date": "August 10, 2022", "title": "Thorne objects to the recommendation", "text": "Thorne's counsel files objections (Document 58), arguing among other things that Southern Pacific shareholders \"were long misled as to their potential claims and the effect of the Hall sale on them.\"", "source": "Plaintiff's Objection to Magistrate's Recommendation, No. 1:21-CV-311-RP, Dkt. 58 (filed Aug. 10, 2022); Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), para. 49", "url": "", "cats": ["courts"], "key": false, "status": "CORRECTED"}, {"src": [224], "date": "2022-09-06", "display_date": "September 6, 2022", "title": "Thorne alleges deception deeper than Hall", "text": "A day after reading Virginia H. Taylor's The Franco-Texan Land Company, Thorne, through counsel, first alleges \"a trail of deceit and conversion\" reaching \"far deeper than Hall's 1868 foreclosure sales\" and naming directors of the Southern Pacific, the Texas and Pacific and the construction company. The filing is Document 60 in No. 1:21-CV-311-RP.", "source": "Plaintiff's Reply to Defendants' Response to Plaintiff's Objection, No. 1:21-CV-311-RP, Dkt. 60 (filed Sept. 6, 2022); Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), paras. 50 to 51", "url": "", "cats": ["courts"], "key": false, "status": "CORRECTED"}, {"src": [225], "date": "2022-09-29", "display_date": "September 29, 2022", "title": "Final judgment in Thorne II", "text": "The court adopts the recommendation and enters final judgment for Union Pacific on its counterclaim, declaring that Thorne owns no stock or equity interest in the defendants and has no presently enforceable rights against them based on Southern Pacific or Texas and Pacific stock certificates or shares. No claim about the 2011 answer was pleaded or decided in either federal suit.", "source": "Final Judgment, No. 1:21-CV-311-RP (W.D. Tex. Sept. 29, 2022); Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), paras. 64 to 65", "url": "", "cats": ["courts"], "key": false, "status": "CORRECTED"}, {"src": [226, 227], "date": "2025-10", "display_date": "October 2025", "title": "A search of original records begins", "text": "Thorne begins searching original records, starting with the corporate records of the California and Texas Railway Construction Company, which by October 31 he finds listed as an active Pennsylvania corporation, Entity No. 53037. Over the following months he works in repositories in Texas, Pennsylvania and Washington, D.C., including the Briscoe Center for American History in Austin.", "source": "Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), paras. 53 to 54", "url": "", "cats": ["construction-co"], "key": false, "status": "CORRECTED"}, {"src": [], "date": "2025-11", "display_date": "November to December 2025", "title": "Newspaper gap certified", "text": "The Marshall Public Library, the publisher of the Jefferson Jimplecute, and the Panola County Historical and Genealogical Association certify in notarized statements that their surviving files lack these issues: the Marshall Messenger from November 19, 1886 to February 15, 1889; the Jefferson Jimplecute from November 13, 1886 to January 28, 1889; and the Panola Watchman from November 15, 1886 to February 1, 1889.", "source": "Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), paras. 44, 54", "url": "", "cats": ["marshall"], "key": false, "status": "VERIFIED"}, {"src": [228], "date": "2026-01-29", "display_date": "January to February 2026", "title": "Finds at the Texas State Archives", "text": "Working through forty-four boxes of Texas and Pacific records at the Texas State Library and Archives on January 29 and 30 and February 3, 2026, Thorne finds and photographs the railroad's annual reports listing construction company stock among its holdings from 1891 through 1902, and its 1931 report.", "source": "Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), para. 55", "url": "", "cats": ["construction-co", "railroad"], "key": false, "status": "CORRECTED"}, {"src": [], "date": "2026-04-24", "display_date": "April 24, 2026", "title": "Reading the records together", "text": "Comparing Union Pacific's file, the 1872 stock statement and the 2011 emails against the 1902 opinion and the archive reports, Thorne first sees, as his complaint puts it, that the 2011 answer left out the conversion of Southern Pacific stock into the construction company's capital. The complaint says the omission appeared only when the records were read together in the order of the events.", "source": "Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), para. 56", "url": "", "cats": ["answers", "construction-co"], "key": true, "status": "VERIFIED"}, {"src": [], "date": "2026-08", "display_date": "2026", "title": "The three-volume history is published", "text": "Thorne publishes his findings, with their sources, as the three-volume history One Machine, Three Lives: Jay Gould's Dirty Little Secret; Thomas A. Scott: The Architect of the Machine; and L. S. Thorne: The Man the Machine Erased.", "source": "Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), para. 56 (published by August 2026)", "url": "", "cats": ["certificate"], "key": false, "status": "VERIFIED"}, {"src": [], "date": "2026-09-01", "display_date": "September 1, 2026", "title": "Fraud claim filed in Harris County", "text": "Thorne files his fraud claim over the 2011 answer in the District Court of Harris County, Texas, 295th Judicial District, No. 2026-63692. Both Union Pacific companies are served September 4.", "source": "Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), para. 66", "url": "", "cats": ["courts"], "key": false, "status": "VERIFIED"}, {"src": [], "date": "2026-10-19", "display_date": "October 19, 2026", "title": "Harris County dismisses for lack of jurisdiction", "text": "The Harris County court grants Union Pacific's special appearance and dismisses the case for want of personal jurisdiction over the defendants. The merits are not reached.", "source": "Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026), paras. 2, 67 to 68 and Ex. F", "url": "", "cats": ["courts"], "key": false, "status": "VERIFIED"}, {"src": [], "date": "2026-11", "display_date": "November 2026", "title": "Fraud complaint filed in Nebraska", "text": "Thorne refiles the claim in the District Court of Douglas County, Nebraska, where both Union Pacific companies have their headquarters. The complaint alleges that the August 3, 2011 answer was materially misleading and seeks $1,875 in damages and a jury's findings.", "source": "Thorne v. Union Pacific Corp., Complaint, District Court of Douglas County, Nebraska (Nov. 2026)", "url": "", "cats": ["courts", "answers"], "key": true, "status": "VERIFIED"}];